  Skill_117317_AwakerSkillBackgroundStory = {
    Text = "\"Pólux, seu Coração Sagrado representa o brilho do Portador de Luz, você deve valorizar essa honra assim como honra a Ele.\" \n Então ele colocou a coroa do Nada sobre a cabeça, sem se atrever a relaxar. \n \"Pólux, não tenha medo, você deve provar o que é a liberdade...\" \n Ele ganhou tudo por causa dessa honra, e também perdeu tudo por causa dessa honra, então percebeu que essa coroa não passava de grilhões invisíveis. \n Ele rasgou a coroa, e aquele coração Vazio brilhou pela primeira vez com uma luz tão intensa quanto a do dia, mas os gritos de raiva e lamento não podiam mais ser ouvidos por outra pessoa."
  },
  Skill_117317_Desc = {
    Text = "Causa <Damage:[Damage:Arg1]> pontos de dano a todos os inimigos, fazendo com que a próxima carta de comando sua neste turno desfrute do efeito \"Redenção da dor\". Coloque 1 carta <DerivativeCardKeywords_118:\"Coração Santo\"> na mão."
