  Skill_119763_AwakerSkillBackgroundStory = {
    Text = "Ela é arrogante. Ela usa a arrogância para esconder o vazio irreparável dentro de si. \n Ela esqueceu quem ela era, ela esqueceu quem ela deveria ser. \n Milhares de crentes do marinheiro se curvam aos seus pés, enquanto ela, em meio a reverências, esqueceu a coisa mais importante — \n ela já se submeteu a esse destino pálido."
  },
  Skill_119763_BattleDesc = {
    Text = "Ganha 2 pontos de poder de cálculo e puxa 2 cartas. No início do próximo turno, sofra [Arg3] pontos de <SacrificeKeyWord:sacrifício>. <RippleKeywords:Réplica>: remova [Arg4] pontos de <SacrificeKeyWord:sacrifício>."
  },
  Skill_119763_Desc = {
    Text = "Ganhe 2 pontos de poder de cálculo, compre 2 cartas. No início do próximo turno, sofra <SacrificeKeyWord:sacrifício> de [Arg1]% da vida máxima. <RippleKeywords:Réplica>: remova <SacrificeKeyWord:sacrifício> de [Float:Arg2]% da vida máxima."
  },
  Skill_119763_EffectNameList = {
    Text = "Remoção de Proporção de Sacrifício"
  },
  Skill_119763_Name = {
    Text = "Hino do mar profundo"
  },
  Skill_119763_PropertyNameList = {
    Text = "$GrowValue1%"
  },
  Skill_119764_AwakerSkillBackgroundStory = {
    Text = "A origem da estátua de marfim nas mãos de Murphy é cercada de controvérsias. \n Alguns dizem que a estátua vem das ruínas do mar profundo exploradas sob a orientação de Murphy, enquanto outros afirmam que a estátua nasceu do coração que pulsava em seu peito junto com a Criança Santa. \n Mas não há dúvida de que essa estátua, que simboliza os laços intrincados entre ela e a cidade de Schraubverschwinden, que permanece silenciosa no fundo do mar da Ignorância, apareceu pela primeira vez aos olhos dos Marchadores de mares no dia em que Murphy se tornou a \"verdadeira Mãe Divina\". \n Desde então, os fiéis também testemunharam Murphy usando esta estátua de marfim para romper as ondas e cortar o mar de sangue. \n O poder absoluto muitas vezes não se limita a um símbolo ilusório. O joelho da humanidade só se ajoelha sob a autoridade da força absoluta."
  },
  Skill_119764_BattleDesc = {
    Text = "Receba <Block:[Block:Arg1]> pontos de escudo e, no início do próximo turno, sofra [Arg7] de <SacrificeKeyWord:sacrifício>. Aplique [Arg3] camadas de <DwmofeiKeywords:Cerimônia de Nascimento> a todos os inimigos, causando [Arg4] vezes <Damage:[Damage:Arg5]> de dano ao inimigo com mais vida, e ganhe [Arg6]% de bônus de <TentacleInjurieIconKeywords:dano de tentáculo>."
  },
  Skill_119764_Desc = {
    Text = "Adquira <Block:[Block:Arg1]> pontos de escudo. No início do próximo turno, sofra <SacrificeKeyWord:sacrifício> de [Arg2]% da vida máxima. Aplique [Arg3] camadas de <DwmofeiKeywords:Cerimônia de Nascimento> a todos os inimigos e cause [Arg4] vezes <Damage:[Damage:Arg5]> pontos de dano ao inimigo com mais vida, recebendo um bônus de [Arg6]% <TentacleInjurieIconKeywords:dano de tentáculo>."
  },
  Skill_119764_EffectNameList = {
    Text = "Escudo, Camadas de Cerimônia de Nascimento, Dano, Aumento de dano de tentáculo"
  },
  Skill_119764_Name = {
    Text = "Princesa Ilusória"
  },
  Skill_119764_OverLimitUtlSkillDesc = {
    Text = "Receba <Block:[Block:Arg1]> pontos de escudo e sofra [Arg7] pontos de <SacrificeKeyWord:sacrifício> no início do próximo turno. Aplique [Arg8] camadas de <DwmofeiKeywords:Cerimônia de Nascimento> a todos os inimigos, causando [Arg4] vezes <Damage:[Damage:Arg5]> pontos de dano ao inimigo com mais vida e desfrutando de um bônus de [Arg6]% de <TentacleInjurieIconKeywords:dano de tentáculo>. Coloque 3 cartas de consumo de potência de cálculo 2 da \"Dança Circular de Luo Yan\" na mão e conceda a ela <DepleteIconKeywords:Consumo> e <PrepareKeypvewords1:Pronto1>."
  },
  Skill_119764_PropertyNameList = {
    Text = "Defesa*GrowValue1,$GrowValue2,Força de ataque*GrowValue3,$GrowValue4％"
  },
  Skill_119765_AwakerSkillBackgroundStory = {
    Text = "Ela é leviana. Ela usa a levianidade para enfrentar a dura realidade. \n Vamos dançar, ela diz, dançar uma dança dedicada aos deuses. \n Agradecemos aos deuses por nos concederem uma causalidade distorcida, um passado desordenado e um futuro imprevisível. \n Sob os holofotes, ela é o único foco de tudo."
  },
  Skill_119765_BattleDesc = {
    Text = "Obtém <Posse:[Arg7]> pontos de Energia da Chave de Prata. Recebe efeitos diferentes dependendo da Postura de Tentáculo: \"Onda\": <TentacleInjurieIconKeywords:dano de tentáculo> +[TentaclePower:Arg1], gera 1 tentáculo. \"Mar Calmo\": ganha <Block:[Block:Arg2]> pontos de escudo, preservando 50% para o próximo turno. \"Onda de Ira\": causa [Arg3] vezes <Damage:[Damage:Arg4]> pontos de dano ao inimigo com mais vida, recebendo um bônus de [Arg5]% de <TentacleInjurieIconKeywords:dano de tentáculo>."
  },
  Skill_119765_Desc = {
    Text = "Adquira [Arg6]% de energia da chave de prata para recarregar a chave de prata. Obtenha diferentes efeitos com base na postura de tentáculo: \"Onda\": <TentacleInjurieIconKeywords:dano de tentáculo> +[TentaclePower:Arg8], gere 1 tentáculo. \"Mar Calmo\": ganhe <Block:[Block:Arg9]> pontos de escudo, preservando 50% até o próximo turno. \"Onda de Ira\": cause [Arg3] vezes <Damage:[Damage:Arg4]> pontos de dano ao inimigo com mais vida e receba um bônus de [Arg5]% de <TentacleInjurieIconKeywords:dano de tentáculo>."
  },
  Skill_119765_EffectNameList = {
    Text = "Dano de tentáculo, Escudo, Dano, Aumento de dano de tentáculo, Eficiência de recarga de Chave de Prata"
  },
  Skill_119765_Name = {
    Text = "Dança Circular de Luo Yan"
  },
  Skill_119765_PropertyNameList = {
    Text = "Força de ataque*GrowValue1,Defesa*GrowValue2,Força de ataque*GrowValue3,$GrowValue4％,$GrowValue5％"
  },
  Skill_119766_AwakerSkillBackgroundStory = {
    Text = "Ela derramou o sangue do cordão umbilical do deus no mar. Ela pediu ao deus um caminho que nunca chegasse ao fim.\nBasta que as bolhas do sonho continuem a existir, ela é a única Mãe Divina."
  },
  Skill_119766_Desc_0 = {
