  Skill_122485_AwakerSkillBackgroundStory = {
    Text = "Não se esqueça do passado, não se esqueça do Grupo de Investigação do Nebuloso.\nEsquecer significa traição.\nE ela, Mouchette, nunca trairá."
  },
  Skill_122485_Desc_0 = {
    Text = "Mouchette ganha <Energy:[Energy:Arg1]> de Fúria. <ExaltIconKeywords:Despertar>: Instâncias de Dano de \"Encontro dramático\" +2. Cada vez que \"Encontro dramático\" é ativado, o Dano Final Temporário do \"golpear\" de Mouchette +25%. Gera imediatamente 1 \"Explosão Humana\" Temporária."
  },
  Skill_122485_Desc_15 = {
    Text = "Mouchette ganha <Energy:[Energy:Arg1]> de Fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: Instâncias de dano de \"Encontro dramático\" +2. O limite de ativação por turno é aumentado para 5. Cada vez que \"Encontro dramático\" é ativado, o Dano Final Temporário de \"golpear\" de Mouchette +25%. Gera imediatamente 2 \"Explosão Humana\" Temporárias com Consumo de potência de cálculo 0."
