  Skill_125372_Desc_1 = {
    Text = "Causar <Damage:[Damage:Arg1]> Dano ao alvo e ao inimigo com a <HPAndShieldMax:maior Vida e Escudo>, infligindo 1 capa de <PVPLostSoulKeyWords:Embriagado>."
  },
  Skill_125372_Name_1 = {
    Text = "Silk sem Sever"
  },
  Skill_125373_AwakerSkillBackgroundStory = {
    Text = "Por que atraí-los? Eles já são impotentes para resistir. \n Por que incitá-los? Até que mais alto e mais amplo, o redemoinho do desejo de poder abrange tudo à vista. \n Porque a essência mundana presa na emoção é difícil de engolir. Porque o corpo não temperado do ordinário é completamente monótono. \n A Terra Sem Sonhos é a recompensa do predador por sobras para sua presa. \n No centro da alegria, não há nada, apenas caos sem fim e esplendor enganoso sem fim."
  },
  Skill_125373_Desc_0 = {
    Text = "Xu obtém <Energy:[Energy:Arg1]> pontos de Fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: Quando cada tipo de Carta de comando de Xu ativar o efeito de <ResonanceKeywords:Ressonância> pela primeira vez por turno, seu Consumo de potência de cálculo básico torna-se 0."
  },
  Skill_125373_Desc_15 = {
    Text = "Xu obtém <Energy:[Energy:Arg1]> pontos de Fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: Quando cada tipo de Carta de comando de Xu ativar o efeito de <ResonanceKeywords:Ressonância> pela primeira vez por turno, seu Consumo de potência de cálculo básico torna-se 0. O limite de acumulação de <WitherKeywords0:Embriagado> aumenta para 15 camadas, e a primeira Carta de comando disparada por Xu a cada turno entra em vigor 1 vez adicional."
  },
  Skill_125373_EffectNameList = {Text = "Fúria"},
  Skill_125373_Name = {
    Text = "Dama da Terra Sem Sonhos"
  },
  Skill_125374_Desc_1 = {
