  Skill_125376_AwakerSkillBackgroundStory = {
    Text = "Desde os tempos antigos até hoje, a palavra amor.\n Não é nada menos que fazer as pessoas se voltarem para o mar do pecado, sem querer voltar atrás."
  },
  Skill_125376_Desc_0 = {
    Text = "[<DevouredIconKeywords:Devorar>: Reduza temporariamente <ExhaustionIconKeywords:FOR> de todos os inimigos em [Exhaustion:Arg1].] Ganhe [Arg2] Arithmetica e aplique [Poison:Arg3] camadas de <IntoxicationIconKeywords:Veneno> a todos os inimigos. Escolha: <WitherKeywords1:Betroth> ou <WitherKeywords2:Enthrall>."
  },
  Skill_125376_Desc_3 = {
    Text = "[<DevouredIconKeywords:Devorar>: Reduza temporariamente <ExhaustionIconKeywords:FORÇA> de todos os inimigos em [Exhaustion:Arg1].] Ganhe [Arg2] Arithmetica e aplique [Poison:Arg3] camadas de <IntoxicationIconKeywords:Venenoso> a todos os inimigos. O efeito da sua próxima <ResonanceKeywords:Ressonância> ativada é dobrado. Escolha: <WitherKeywords1:Noivado> ou <WitherKeywords2:Encantar>."
  },
