  },
  Skill_125376_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Devorar>: Reduz temporariamente a <ExhaustionIconKeywords:FOR> de todos os inimigos em [Exhaustion:Arg1].] Ganha [Arg2] de Poder de cálculo, <EmbryoFusionIconKeywords:Fusão de embriões> +[Arg4], e inflige [Poison:Arg3] <plural value=\"[Poison:Arg3]\" singular=\"capa\" plural=\"capas\"> de <IntoxicationIconKeywords:Envenenamento> em todos os inimigos. Escolha: <WitherKeywords1:Promessa> ou <WitherKeywords2:Roubo de Alma>."
  },
  Skill_125376_OverLimitUtlSkillDesc_3 = {
    Text = "[<DevouredIconKeywords:Devorar>: Reduz temporariamente a <ExhaustionIconKeywords:FOR> de todos os inimigos em [Exhaustion:Arg1].] Ganha [Arg2] de Poder de cálculo, <EmbryoFusionIconKeywords:Fusão de embriões>+[Arg4], e inflige [Poison:Arg3] <plural value=\"[Poison:Arg3]\" singular=\"capa\" plural=\"capas\"> de <IntoxicationIconKeywords:Envenenamento> em todos os inimigos. O próximo efeito de <ResonanceKeywords:Resonância> ativado por si mesmo é dobrado. Escolha: <WitherKeywords3:Promessa> ou <WitherKeywords4:Roubo de Alma>."
