  Skill_130929_AwakerSkillBackgroundStory = {
    Text = "Agitando alegremente o enorme canhão, pulando para o campo de batalha. \n Sem se importar com preocupações, sem se importar com perigos, porque isso é tão insignificante em comparação com amigos. \n \"Amigo, problema! Mosk, entre em cena!\""
  },
  Skill_130929_BattleDesc_0 = {
    Text = "Mosk ganha <Energy:[Energy:Arg1]> pontos de Fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: compre 1 carta \"Carregar!\". Após liberar a perseguição, na próxima explosão de Fúria de Mosk, ela recebe um aumento de dano de tentáculo de +[Arg2] %, acumulando no máximo [Arg3] vezes."
  },
  Skill_130929_BattleDesc_15 = {
    Text = "Mosk ganha <Energy:[Energy:Arg1]> Fúria. <ExaltIconKeywords:Despertar>: Compra 1 \"Carregar\". Após Mosk desencadear Caça, sua próxima Fúria Explosiva ganha um Aumento de dano de tentáculo extra de [Arg2]%, e a próxima Fúria Explosiva causa <RealDamage:Dano Fixo> igual a [Arg4]% da Vida máxima ao inimigo com mais Vida, acumulando até [Arg3] <plural value=\"[Arg3]\" singular=\"vez\" plural=\"vezes\">."
  },
  Skill_130929_Desc_0 = {
    Text = "Mosk ganha [Arg5]% de Aliemus Base. <ExaltIconKeywords:Despertar>: Compra 1 \"Carregar\". Após Mosk Liberar uma Caçada, a próxima Fúria Explosiva de Mosk ganha adicionalmente [Arg2]% de Aumento de dano de tentáculo, acumulando até [Arg3] vezes."
  },
  Skill_130929_Desc_15 = {
