  Skill_131192_Desc = {
    Text = "Reduz o Consumo de potência de cálculo de todas as cartas com <ErosionColorInkKeywords:Distorção de Percepção> na mão em 1; para cada carta, concede ao Corpo Desperto com a menor Fúria <Energy:5> pontos de Fúria; depois restaura as cartas com <ErosionColorInkKeywords:Distorção de Percepção> em todos os locais. Após Disparar uma carta neste turno, não aplica mais <ErosionColorInkKeywords:Distorção de Percepção> a outras cartas."
  },
  Skill_131192_Name = {
    Text = "Verdade Proibida"
  },
  Skill_131241_Desc = {
    Text = "O jogador ganha [Power:Arg1] pontos <PowerIconKeywords:Força>, <Block:[Block:Arg2]> pontos de escudo, [Heal:Arg3] pontos de cura, [TentaclePower:Arg4] pontos <TentacleInjurieIconKeywords:Dano de tentáculo>, [Counterattack:Arg5] camadas <RetaliateIconKeywords:Contrataque>, causando <Damage:[Damage:Arg6]> pontos de dano aos inimigos na frente [Arg7] vezes, [Poison:Arg8] camadas <IntoxicationIconKeywords:Envenenamento>, aplicando [Exhaustion:Arg9] camadas <ExhaustionIconKeywords:Exaustão>."
  },
  Skill_131241_Name = {
