  Skill_131365_Name = {
    Text = "Fios do Destino em Seus Devidos Lugares"
  },
  Skill_131438_Desc = {
    Text = "Após a fase de compra de cartas, se estiver na mão, escolha 1 carta de comando aleatória entre 2 cartas e Disparar forçado, fazendo-a ter efeito 2 vezes. \n Após disparar, o custo de poder da próxima carta de comando será reduzido a 0, e a carta disparada terá efeito adicional de 2 vezes. Após disparar [Arg1] vezes, consome ([Arg2]/[Arg1])."
  },
  Skill_131438_Name = {Text = "Marionete"},
  Skill_131654_Desc = {
    Text = "Disparar, remove o valor de Fúria do Corpo Desperto designado e, em seguida, faz com que ele ganhe o valor de Fúria equivalente a 1 vez a Fúria base."
