  },
  Skill_131856_AwakerSkillBackgroundStory = {
    Text = "Olhos, ouvidos, língua, pele, cérebro — sensações espalhadas por todo o corpo.\nO amor e a ternura compartilhados te envolverão para sempre, até a morte —"
  },
  Skill_131856_BattleDesc_0 = {
    Text = "Saya obtém <Energy:[Energy:Arg1]> pontos de Fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: Após usar \"Forno Carmesim\", adiciona <ErosionColorInkKeywords:Distorção de Percepção> às Cartas de comando de outros Corpos Despertos que não possuam \"<DestructionKeywords:Destruir>\". As primeiras 3 vezes por turno que Disparar uma Carta de comando com <ErosionColorInkKeywords:Distorção de Percepção> fazem Saya e o Corpo Desperto ao qual a Carta de comando pertence obterem <Energy:[Energy:Arg2]> pontos de Fúria."
  },
  Skill_131856_BattleDesc_15 = {
    Text = "Saya obtém <Energy:<Energy:[Energy:Arg1]>> pontos de Fúria. <ExaltIconKeywords:<ExaltIconKeywords:Despertar do Conhecimento Espiritual>>: Após usar \"Forno Carmesim\", Saya obtém <Energy:<Energy:[Energy:Arg4]>> pontos de Fúria e 1 camada de \"<KaiHuajishu:<KaiHuajishu:Gineceu>>\". Anexa <ErosionColorInkKeywords:<ErosionColorInkKeywords:Distorção de Percepção>> às Cartas de comando de outros Corpos Despertos em cada local que não possuam \"<DestructionKeywords:<DestructionKeywords:Destruir>>\". As primeiras 3 vezes por turno que Disparar uma Carta de comando com <ErosionColorInkKeywords:<ErosionColorInkKeywords:Distorção de Percepção>> fazem Saya e o Corpo Desperto ao qual pertence essa Carta de comando obterem <Energy:<Energy:[Energy:Arg2]>> pontos de Fúria."
  },
  Skill_131856_Desc_0 = {
    Text = "Saya obtém [Arg3]% de Fúria base. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: Após usar \"Forno Carmesim\", anexa <ErosionColorInkKeywords:Distorção de Percepção> às cartas de comando de outros Corpos Despertos que não possuam \"<DestructionKeywords:Destruir>\". As primeiras 3 vezes por turno que uma carta de comando com <ErosionColorInkKeywords:Distorção de Percepção> for disparada, Saya e o Corpo Desperto ao qual a carta pertence obtêm <Energy:[Energy:Arg2]> pontos de Fúria."
  },
  Skill_131856_Desc_15 = {
    Text = "Saya obtém [Arg3]% de Fúria base. <ExaltIconKeywords:<ExaltIconKeywords:Despertar do Conhecimento Espiritual>>: Após usar \"Forno Carmesim\", Saya obtém <Energy:<Energy:[Energy:Arg4]>> pontos de Fúria e 1 camada de \"<KaiHuajishu:<KaiHuajishu:Gineceu>>\". Anexa <ErosionColorInkKeywords:<ErosionColorInkKeywords:Distorção de Percepção>> às cartas de comando de outros Corpos Despertos que não possuam \"<DestructionKeywords:<DestructionKeywords:Destruir>>\". As primeiras 3 vezes por turno que uma carta de comando com <ErosionColorInkKeywords:<ErosionColorInkKeywords:Distorção de Percepção>> for disparada, Saya e o Corpo Desperto ao qual a carta pertence obtêm <Energy:<Energy:[Energy:Arg2]>> pontos de Fúria."
  },
  Skill_131856_EffectNameList = {Text = "#N/A"},
