  Skill_131857_AwakerSkillBackgroundStory = {
    Text = "Antes de chegar ao mundo que sempre buscou, o mundo onde não precisaria mais se esconder.\nTudo que estiver no caminho é um \"inimigo\" que deve ser derrotado."
  },
  Skill_131857_BattleDesc_0 = {
    Text = "Causa <Damage:[Damage:Arg1]> pontos de dano. Ganha <Energy:[Energy:Arg2]> pontos de aliemus"
  },
  Skill_131857_BattleDesc_2 = {
    Text = "Causa <Damage:[Damage:Arg1]> pontos de dano. Obtém <Energy:[Energy:Arg2]> pontos de Fúria. <EmbryoFusionIconKeywords:Fusão Embrionária> +[Blood:Arg3]."
  },
  Skill_131857_Desc_0 = {
