  },
  Skill_131857_Desc_2 = {
    Text = "Causa <Damage:[Damage:Arg1]> pontos de Dano. Saya obtém <Energy:[Energy:Arg2]> pontos de Fúria. <EmbryoFusionIconKeywords:Fusão de embriões> +[Blood:Arg4], quanto menor a Vida atual, maior o Efeito, podendo aumentar até 100%"
