  },
  Skill_132433_Desc_0 = {
    Text = "Causa <Damage:[Damage:Arg1]> pontos de dano. Embaralhe [Arg2] cartas de \"divisão glandular\" na pilha de descarte. <RippleKeywords:Réplica>: Ganha <Energy:[Energy:Arg3]> pontos de aliemus."
