  Skill_133325_BattleDesc_1 = {
    Text = "Seleciona um aliado, fazendo-o obter <Heal:[Heal:Arg4]> <PVPFeatheredSeedsKeyWords:Gineceu> e Vida equivalente; a cada [Arg2] de Poder de cálculo consumido, o <PVPFeatheredSeedsKeyWords:Gineceu> e a Vida equivalente aumentam em [Arg3]."
  },
  Skill_133325_Desc_1 = {
    Text = "Escolha um aliado para ganhar <Heal:[Heal:Arg1]> de <PVPFeatheredSeedsKeyWords:Gineceu> e uma quantidade igual de Vida. Para cada [Arg2] de Poder de cálculo gasto, o <PVPFeatheredSeedsKeyWords:Gineceu> e a Vida igual aumentam em [Arg3]."
  },
  Skill_133325_Name_1 = {
    Text = "Propagação"
  },
  Skill_133346_Desc_1 = {
    Text = "Causa <PVPSeriousInjuryKeywords:Lesão grave>, <PVPPenetrateKeywords:Penetração>, <DelayKeywords:Latência>: Recupera <Heal:[Heal:Arg1]> de Vida para todos os aliados. A cada [Arg2] Escudo dispersado por <PVPSeriousInjuryKeywords:Lesão grave> ou cura por <DelayKeywords:Latência>, a vida recuperada aumenta em +[Arg3]."
  },
