  Skill_133347_Desc_1 = {
    Text = "<PVPWeaponKeywords:Roda do destino>: Preservada após a morte desta Roda do destino. Quando o Portador morre e ao fim dos [Arg2] turnos seguintes no Estado de morte, os demais aliados obtêm <Heal:[Heal:Arg1]> de <PVPFeatheredSeedsKeyWords:Gineceu> e Vida."
  },
  Skill_133347_Name_1 = {
    Text = "Que o mundo se transforme em fragrância"
  },
  Skill_133348_Desc_1 = {
    Text = "<PVPWeaponKeywords:Roda do destino>: Após equipar, as descrições de \"golpear,\" \"Habilidade\" e \"Fúria Explosiva\" do Portador tornam–se não identificáveis, mas cada instância de Dano, Escudo e cura é aleatoriamente aumentada em [Arg1]%~[Arg2]%."
  },
  Skill_133348_Name_1 = {
    Text = "Conto de fadas na lama"
  },
  Skill_133365_AwakerSkillBackgroundStory = {
    Text = "Ela já ouviu incontáveis vezes o som dos fios se rompendo.\nUm reencontro que nunca aconteceu. Uma confissão que nunca foi dita. Uma criança que nunca nasceu.\nUma música que nunca veio ao mundo. Uma guerra que nunca foi vencida. Uma civilização que nunca sobreviveu.\nOs fios tecem. Os fios se rompem. Os fios retornam àquela grande teia.\nA divindade do destino já sabia há muito: nada jamais perece de verdade, nada jamais existiu de verdade."
  },
  Skill_133365_Desc_0 = {
    Text = "Ganha <Block:[Block:Arg1]> pontos de Escudo. Outros Corpos Despertos ganham <Energy:[Energy:Arg2]> pontos de Fúria. Na próxima vez que \"Tecelagem Eterna\" gerar um \"<DerivativeCardKeywords_138:Chamar o destino>\" adicional, coloque-o no Mazo de robo e no Monte de descarte."
  },
  Skill_133365_EffectNameList = {
    Text = "Escudo, Loucura"
  },
  Skill_133365_Name = {
    Text = "Rede da Morte"
  },
  Skill_133365_PropertyNameList = {
