  },
  Skill_133366_AwakerSkillBackgroundStory = {
    Text = "Desde o primeiro dia de seu nascimento, ela viu os fios do destino se estenderem.\nSeguindo o trajeto dos fios, ela cruzou o portal e aceitou seu destino infinito, o destino de uma prisioneira.\nOs fios atravessaram a roda de fiar chamada Moirai, atravessaram muralhas e estreitos, atravessaram juramentos e mentiras, atravessaram cada alma que acreditava estar fazendo suas próprias escolhas.\nNesta ilusão de liberdade, a roda de fiar gira, incessante desde tempos imemoriais."
  },
  Skill_133366_Desc_0 = {
    Text = "Causa [FateCut:Arg1] pontos de <CutKeywords:Destinação Fatal> a todos os inimigos, gera 1 carta \"<DerivativeCardKeywords_138:Fios Guia>\" e a coloca na mão. <SilkKeywords1:>"
