  Skill_142695_AwakerSkillBackgroundStory = {
    Text = "Ele preservou as partes mais vívidas e encantadoras de todos os seus entes queridos, e infligiu os tormentos mais cruéis e prolongados a todos os seus inimigos.\nA cada noite de festas e brindis, ele caía às gargalhadas em um oceano formado por cascas vazias."
  },
  Skill_142695_BattleDesc = {
    Text = "Remove o Estado de <ExhaustionIconKeywords:Redução de força> de si mesmo. Reduz temporariamente [Exhaustion:Arg1] pontos de <ExhaustionIconKeywords:Força> de todos os inimigos. Causa <RealDamage:Dano Fixo>( [Arg3] ) equivalente a [Arg2]% do Dano de tentáculo ao inimigo com menos Vida. Se o eliminar, gera 1 carta permanente de \"Gaunt\" <DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> e a coloca na mão. Podem ser geradas no máximo 3 cartas permanentes de \"Gaunt\" por batalha."
  },
  Skill_142695_Desc = {
    Text = "Remove o próprio estado <ExhaustionIconKeywords:Redução de força>. A <ExhaustionIconKeywords:FOR> de todos os inimigos –[Exhaustion:Arg8] temporariamente. Causa <RealDamage:Dano Fixo> igual a [Arg2]% do Dano de tentáculo ao inimigo com menos Vida. Se isso eliminar o alvo, gera 1 \"Gaunt\" permanente<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> na mão. Máximo de 3 \"Gaunts\" permanentes gerados por batalha."
  },
  Skill_142695_EffectNameList = {
    Text = "Redução Temporária de Força,Aumento de dano de tentáculo,Nível de Gaunt"
  },
