  Skill_142700_AwakerSkillBackgroundStory = {
    Text = "\"O que você deseja?\"\nForça, ordem, recuperar o que foi perdido, lavar a afronta com Sangue...\nEle mergulhou em um silêncio longo e sombrio, mas na verdade já tinha uma resposta há muito tempo — uma resposta sem solução.\nEle queria ver o sol nascer e se pôr, queria que tudo fosse como de costume."
  },
  Skill_142700_BattleDesc_0 = {
    Text = "Pontos obtém <Energy:[Energy:Arg1]> pontos de Fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: Para cada 3 cartas de \"Gaunt\" no baralho, \"Caçada Implacável\" obtém 1 camada adicional de <BattueKeywords:Caçada em Matilha>. Para cada 1 Carta de Pontos Disparada, o Efeito de Redução Temporária de Força da próxima \"Caçada Implacável\" aumenta em [Arg3]%, podendo ser ativado no máximo 3 vezes por turno."
  },
  Skill_142700_BattleDesc_15 = {
    Text = "Pontos ganha <Energy:[Energy:Arg1]> Fúria. <ExaltIconKeywords:Despertar>: Para cada 2 \"Gaunts\"<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> no baralho, \"Caçada Implacável\" ganha 1 acúmulo extra de <BattueKeywords:Caçada em Matilha>. Para cada 1 Carta de Pontos jogada, o efeito de Redução Temporária de Força da próxima \"Caçada Implacável\" +[Arg3]%, ativando até 3 vezes por turno. Ganha +<Energy:[Energy:Arg4]> Fúria no 1º Disparo de \"Golpear\" e \"Defesa\" de cada turno."
  },
  Skill_142700_Desc_0 = {
    Text = "Pontos obtém [Arg2]% de Aliemus Base. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: Para cada 3 cartas de \"Gaunt\" no baralho, \"Caçada Implacável\" obtém 1 camada de <BattueKeywords:Caçada em Matilha>. Para cada 1 Carta de Pontos Disparada, o Efeito de Redução Temporária de Força da próxima \"Caçada Implacável\" aumenta em [Arg3]%, podendo ser ativado no máximo 3 vezes por turno."
  },
  Skill_142700_Desc_15 = {
    Text = "Pontos ganha [Arg2]% de Aliemus Base. <ExaltIconKeywords:Despertar>: Para cada 2 \"Gaunts\"<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> no baralho, \"Caçada Implacável\" ganha 1 acúmulo de <BattueKeywords:Caçada em Matilha>. Para cada 1 Carta de Pontos jogada, o efeito de Redução Temporária de Força da próxima \"Caçada Implacável\" +[Arg3]%, ativando até 3 vezes por turno. Ganha +<Energy:[Energy:Arg4]> Fúria no 1º Disparo de \"Golpear\" e \"Defesa\" de cada turno."
