  Skill_142846_AwakerSkillBackgroundStory = {
    Text = "Nem o ouvido humano nem a atual Tecnologia Silvercore conseguem extrair qualquer informação útil do assobio de caça de Pontos.\nNo entanto, todos os indivíduos assimilados por Ebwynnos parecem se adaptar rapidamente a seguir as ordens d'O Assobio."
  },
  Skill_142846_Desc = {
    Text = "Se for a primeira vez que é liberada nesta batalha, gera 3 tipos diferentes de \"Gaunt\" <DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> e os coloca na mão, obtendo <Block:[Block:Arg1]> pontos de Escudo. Para cada 4 cartas permanentes de Gaunt possuídas, 1 delas é melhorada para \"Gêmeos Conjuntos\". Caso contrário, compra 3 cartas de \"Gaunt\"."
  },
  Skill_142846_EffectNameList = {
