  Skill_144491_AwakerSkillBackgroundStory = {
    Text = "A ganância é a verdadeira cor da natureza humana.\nNinguém consegue resistir à tentação do açúcar, nem mesmo a própria Fada Madrinha.\nCaraboo sorriu amplamente, exibindo uma boca cheia de dentes pontudos e negros como breu."
  },
  Skill_144491_BattleDesc_0 = {
    Text = "Caraboo ganha <Energy:[Energy:Arg1]> de Fúria. <ExaltIconKeywords:Despertar>: Após usar \"Forno Carmesim\", a próxima <DerivativeCardKeywords_160:\"Bênção Milagrosa\"> custa -3 de Poder de cálculo, e cada opção de <FaxianKeywords:descoberta> é aprimorada para um conjunto que contém 1 carta de <DerivativeCardKeywords_152:\"Bênção\"> a mais. Escolha 1 conjunto para embaralhar no seu Mazo de robo."
  },
  Skill_144491_BattleDesc_15 = {
    Text = "Caraboo ganha <Energy:[Energy:Arg1]> de Fúria. <ExaltIconKeywords:Despertar>: Após usar \"Forno Carmesim\", a próxima <DerivativeCardKeywords_160:\"Bênção Milagrosa\"> custa -3 de Poder de cálculo, e cada opção de <FaxianKeywords:descoberta> é aprimorada para um conjunto que contém 2 cartas de <DerivativeCardKeywords_152:\"Bênção\"> a mais. Escolha 1 conjunto para embaralhar no seu Mazo de robo. Após jogar uma carta de \"Bênção\", Fusão de embriões +10. Este efeito de fusão aumenta com base nos seus Pontos de vida perdidos, até +100%."
  },
  Skill_144491_Desc_0 = {
    Text = "Caraboo ganha [Arg2]% de Fúria Básica. <ExaltIconKeywords:Despertar>: Após usar \"Forno Carmesim\", a próxima <DerivativeCardKeywords_160:\"Bênção Milagrosa\"> custa -3 de Poder de cálculo, e cada opção de <FaxianKeywords:descoberta> é aprimorada para um conjunto que contém 1 carta de <DerivativeCardKeywords_152:\"Bênção\"> a mais. Escolha 1 conjunto para embaralhar no seu Mazo de robo."
  },
  Skill_144491_Desc_15 = {
    Text = "Caraboo ganha [Arg2]% de Fúria Básica. <ExaltIconKeywords:Despertar>: Após usar \"Forno Carmesim\", a próxima <DerivativeCardKeywords_160:\"Bênção Milagrosa\"> custa -3 de Poder de cálculo, e cada opção de <FaxianKeywords:descoberta> é aprimorada para um conjunto que contém 2 cartas de <DerivativeCardKeywords_152:\"Bênção\"> a mais. Escolha 1 conjunto para embaralhar no seu Mazo de robo. Após jogar uma carta de <Blessing:Bênção>, Fusão de embriões +10. Este efeito de fusão aumenta com base nos seus Pontos de vida perdidos, até +100%."
  },
