  Skill_145675_AwakerSkillBackgroundStory = {
    Text = "Na verdade, Ogier havia esquecido há muito como aquele castelo realmente era.\nMas agora, ele poderia forjar novas muralhas a partir das preces guardadas no fundo de seu coração.\nSe, sob sua proteção, as risadas do povo ainda pudessem ser ouvidas, e flores familiares pudessem mais uma vez desabrochar pelos campos...\nEntão aquele coração — há muito transformado em algo diferente — ainda teria uma razão para permanecer neste mundo."
  },
  Skill_145675_BattleDesc_0 = {
    Text = "Obtém <Block:[Block:Arg1]> pontos de Escudo, obtém [Power:Arg2] pontos de <PowerIconKeywords:Força>, consome toda a <KuangNu:Corrente Sombria>, cada camada consumida aumenta o Escudo e a Força causados em 33%, obtém 1 camada de <ShuZui:Autoculpa>."
  },
  Skill_145675_BattleDesc_3 = {
    Text = "Obtém <Block:[Block:Arg1]> pontos de Escudo, obtém [Power:Arg2] pontos de <PowerIconKeywords:Força>, consome toda a <KuangNu2:Corrente Sombria>, cada camada consumida aumenta o Escudo e a Força causados em 50%, obtém 1 camada de <ShuZui:Autoculpa>."
  },
  Skill_145675_Desc_0 = {
    Text = "Obtém <Block:[Block:Arg3]> pontos de Escudo, obtém [Power:Arg4] pontos de <PowerIconKeywords:Força>, consome toda a <KuangNu:Corrente Sombria>, cada camada consumida aumenta o Escudo e a Força causados em 33%, obtém 1 camada de <ShuZui:Autoculpa>."
