  },
  Skill_145675_OverLimitUtlSkillDesc_0 = {
    Text = "Obtém <Block:[Block:Arg1]> pontos de Escudo, obtém [Power:Arg5] pontos de <PowerIconKeywords:Força>, consome toda a <KuangNu:Corrente Sombria>, cada camada consumida aumenta o Escudo e a Força causados em 33%, obtém 1 camada de <ShuZui:Autoculpa>."
