  Skill_146012_Desc = {
    Text = "Não pode ser jogado. Enquanto estiver na mão:\nTodos os inimigos causam 25% mais Dano à sua equipe.\nTodas as Cartas de comando de Lotan: Cetarcon se tornam <DerivativeCardKeywords_154:\"Duelo Mortal\">.\nNo início de cada turno, compra 1 <DerivativeCardKeywords_154:\"Duelo Mortal\">."
  },
  Skill_146012_Name = {
    Text = "Espadão·Queda da Baleia"
  },
  Skill_146013_AwakerSkillBackgroundStory = {
    Text = "Apenas em raríssimas ocasiões Lotan recolhe sua espada.\nAqueles olhos heterocromáticos observam com frieza. Recuar a guarda é sempre apenas para desferir um golpe ainda melhor."
  },
  Skill_146013_BattleDesc_0 = {
    Text = "Adquira <Block:[Block:Arg1]> pontos de escudo. Adquira <Energy:[Energy:Arg2]> pontos de aliemus"
  },
  Skill_146013_BattleDesc_2 = {
    Text = "Obtém <Block:[Block:Arg1]> pontos de Escudo. Obtém <Energy:[Energy:Arg2]> pontos de Fúria. Na primeira vez que for disparada por turno, compra 1 carta de \"Lâmina Longa·Ruína\" ( [Arg4]/1 )."
