  },
  Skill_146015_OverLimitUtlSkillDesc = {
    Text = "Consome <DerivativeCardKeywords_153:\"Grande Lâmina: Queda da Baleia\"> para usar. Obtém [Power:Arg3] <PowerIconKeywords:STR>. Causa <Damage:[Damage:Arg1]> de dano de Golpe Crítico garantido ao inimigo com o maior dano, que recebe um Bônus de STR de [Arg2]%. Para cada +1 de dano que <DerivativeCardKeywords_153:\"Grande Lâmina: Queda da Baleia\"> está fazendo o alvo causar a você, \"Separação de Mundus\" causa +[Arg4] de dano. <DerivativeCardKeywords_154:>"
  },
