  Skill_21615_AwakerSkillBackgroundStory = {
    Text = "A memória de Ogier está fragmentada devido ao fenômeno de erosão.\n Ele se lembra das risadas no baile, mas esqueceu o nome do protagonista do baile; ele se lembra de seu treinamento na ordem dos cavaleiros, mas não sabe por que o duque o fez se tornar um cavaleiro tão jovem; ele se lembra de ter perecido sob os pés dos cavaleiros de ferro, mas não consegue se recordar do sorriso que estava protegendo.\n Ninguém pode culpá-lo, ele já cumpriu todas as responsabilidades de um cavaleiro — incluindo sacrificar sua vida pela vontade de proteger."
  },
  Skill_21615_Desc_0 = {
    Text = "Dispersa <FragileIconKeywords:frágil>. Ganha <Block:[Block:Arg1]> de escudo. Ganha [Power:Arg2] de <PowerIconKeywords:força> temporária"
  },
  Skill_21615_Desc_2 = {
    Text = "Se possuir <FragileIconKeywords:frágil>, dissipe e ganhe <Block:[Block:Arg3]> de escudo. Ganhe <Block:[Block:Arg1]> de escudo. Ganhe [Power:Arg2] de <PowerIconKeywords:força> temporária"
  },
  Skill_21615_EffectNameList_0 = {
    Text = "Escudo, Força"
  },
  Skill_21615_EffectNameList_2 = {
    Text = "Dispersa, concede escudo, escudo, força"
  },
  Skill_21615_Name = {
    Text = "Sete artes, transmitir a virtude"
  },
  Skill_21615_OverLimitUtlSkillDesc_0 = {
    Text = "Dispersa o Estado <FragileIconKeywords:Frágil> próprio. Obtém <Block:[Block:Arg1]> pontos de Escudo. Obtém [Power:Arg2] pontos de <PowerIconKeywords:Força> Temporária. O Escudo obtido é aumentado em 200%. O número de vezes que Ogier causa Dano +1, por 3 rodadas."
  },
  Skill_21615_OverLimitUtlSkillDesc_2 = {
    Text = "Se possuir <FragileIconKeywords:Frágil>, dissipe e ganhe <Block:[Block:Arg3]> de escudo. Ganhe <Block:[Block:Arg1]> de escudo. Ganhe [Power:Arg2] de <PowerIconKeywords:Força> temporária neste turno. O escudo ganho aumenta em 200%. Ogier causa +1 dano por 3 turnos"
  },
  Skill_21615_PropertyNameList_0 = {
    Text = "Defesa *GrowValue1,Ataque *GrowValue2"
  },
