  Skill_3981_AwakerSkillBackgroundStory = {
    Text = "Uma linhagem herdada de outras raças, considerada herética. \n Somente acreditando em sua nobreza, acreditando em sua grandeza, pode-se sobreviver neste mundo cruel. \n O manuscrito deixado pelo tio Ornn, com a magnífica cidade antiga do Mar Profundo descrita nele, é seu único consolo espiritual. \n \"No momento da explosão do sangue, certamente receberá o supremo poder do Mar Profundo, certo?\""
  },
  Skill_3981_Desc = {
    Text = "Recupere <Heal:[Heal:Arg3]> de Vida e dissipe <WeaknessIconKeywords:Enfraquecer> de si mesmo, aplique [Arg4] <plural value=\"[Arg4]\" singular=\"capa\" plural=\"capas\"> de <VulnerabilityIconKeywords:Vulnerável> a todos os inimigos. <TentacleInjurieIconKeywords:Dano de tentáculo> +[TentaclePower:Arg1]. <RetaliateIconKeywords:Contrataque> +[Counterattack:Arg2]. Antes do início do próximo turno, para cada Ataque recebido, um tentáculo contra-ataca o agressor."
  },
  Skill_3981_EffectNameList = {
    Text = "Recuperação, dano de tentáculo, contra-ataque"
  },
  Skill_3981_Name = {
    Text = "Sangue herético"
  },
  Skill_3981_OverLimitUtlSkillDesc = {
    Text = "Recupera <Heal:[Heal:Arg3]> pontos de Vida e dispersa o Estado de <WeaknessIconKeywords:Fraqueza> de si mesmo, aplicando [Arg4] camadas de <VulnerabilityIconKeywords:Vulnerável> a todos os inimigos. <TentacleInjurieIconKeywords:Dano de tentáculo> +[TentaclePower:Arg1]. <RetaliateIconKeywords:Contrataque> +[Counterattack:Arg2]. Antes do início do próximo turno, a cada 1 Ataque recebido, 1 tentáculo realiza um Contrataque contra o atacante. Faz 1 tentáculo Atacar 5 vezes, obtendo um Contrataque equivalente a 25% do Dano causado."
