  },
  Skill_4018_Desc_15 = {
    Text = "Nautila ganha <Energy:[Energy:Arg1]> Fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: Escudos do personagem e <RetaliateIconKeywords:Contrataque> aplicados por Nautila +[Arg2]%, e o <RetaliateIconKeywords:Contrataque> Fixo causado por todos os Corpos Despertos +[Arg3]%."
