  Skill_4055_AwakerSkillBackgroundStory = {
    Text = "No vasto oceano, um barco solitário balança com as ondas do mar. \n Eles suplicam, imploram e choram, esperando que a deusa branca os leve para longe do mar e os traga de volta à terra natal. \n No mastro central, a garota de vestido branco ergue a cabeça e avista um pássaro branco. \n \"Dê-me o leme, eu os levarei para casa.\""
  },
  Skill_4055_BattleDesc_0 = {
    Text = "Dissipar o estado de <HeavyInjuryKeywords: Peso> em si mesmo, recuperar <Heal:[Heal:Arg1]> pontos de vida e ganhar 1 aritmética. Ao sofrer dano fatal nesta batalha, reviver e recuperar [Arg2]% (<Heal:[Arg3]>) de vida; cada batalha pode ativar esta habilidade apenas uma vez"
  },
  Skill_4055_BattleDesc_3 = {
    Text = "Dissipa o estado de <HeavyInjuryKeywords:Lesão grave> em si mesmo, recupera <Heal:[Heal:Arg1]> pontos de vida e ganha 1 poder de cálculo. Ao sofrer dano fatal nesta batalha, revive, recupera [Arg2]% (<Heal:[Arg3]>) de vida e todos os corpos despertos ganham <Energy:[Energy:Arg4]> pontos de fúria; após ser ativada, precisa de um intervalo de 6 turnos para poder aplicar novamente o efeito de ressurreição."
  },
  Skill_4055_Desc_0 = {
    Text = "Dissipa o estado de <HeavyInjuryKeywords:reconhecimento> de si mesmo, recupera <Heal:[Heal:Arg1]> pontos de vida e ganha 1 capacidade. Ao sofrer dano fatal nesta batalha, revive e recupera [Arg2]% da vida, podendo ser ativado apenas uma vez por batalha"
  },
  Skill_4055_Desc_3 = {
    Text = "Dissipa o estado de <HeavyInjuryKeywords:Lesão grave> em si mesmo, recupera <Heal:[Heal:Arg1]> pontos de vida e ganha 1 poder de cálculo. Ao sofrer dano fatal nesta batalha, revive, recupera [Arg2]% da vida e todos os Corpos Despertos ganham <Energy:[Energy:Arg4]> pontos de fúria; após a ativação, é necessário esperar 6 turnos para que o efeito de ressurreição possa ser aplicado novamente."
