  Skill_4076_AwakerSkillBackgroundStory = {
    Text = "Venus, vestida em pele, coloque seu pé nas costas do escravo! \nPrenda correntes em seus pescoços e atravesse seus corações marcados com a agulha espinhal"
  },
  Skill_4076_Desc_0 = {
    Text = "Aleatoriamente cause <Damage:[Damage:Arg1]> pontos de dano [Arg2] vezes, com cada dano se beneficiando de [Arg4]% de <RetaliateIconKeywords:contra-ataque>. Cada ataque reduz temporariamente os [Exhaustion:Arg3] pontos de <ExhaustionIconKeywords:FORÇA> do alvo. <TransitionIconKeywords:salto>: Consome 5 camadas de <DreamGuide:atração onírica>. Se bem-sucedido, reembolsa a aritmética consumida e causa um dano adicional 2 vezes; caso contrário, ganha 2 camadas de <DreamGuide:atração onírica>."
  },
  Skill_4076_Desc_1 = {
    Text = "Aleatoriamente cause <Damage:[Damage:Arg1]> pontos de dano [Arg2] vezes, este dano se beneficia de [Arg4]% de bônus de <RetaliateIconKeywords:contra-ataque>, cada ataque reduz os [Exhaustion:Arg3] pontos temporários de <ExhaustionIconKeywords:força> do alvo. A taxa de crítico deste cartão aumenta em 25%. <TransitionIconKeywords:salto>: Consome 5 camadas de <DreamGuide:atração onírica>, se bem-sucedido, reembolsa a aritmética consumida e causa um dano adicional 2 vezes, caso contrário, ganha 2 camadas de <DreamGuide:atração onírica>."
