  Skill_4120_AwakerSkillBackgroundStory = {
    Text = "Ela pediu ao gladiador para matá-la. \n \"Logo, eles vão me encontrar, me humilhar e cortar minha cabeça, assim como fizeram com meus pais. \n Não quero morrer nas mãos dessas criaturas desprezíveis, mas você... é diferente deles. \n Este é o meu único pedido — mate-me.\" \n O gladiador riu alto, sua voz reverberando no peito, fazendo as correntes em seu corpo tilintarem. \n Ele não se deixou impressionar pelas palavras dela, mas nunca recusou sangue fresco que lhe era oferecido."
  },
  Skill_4120_Desc_0 = {
