  Skill_4137_AwakerSkillBackgroundStory = {
    Text = "A dedução é uma lógica que só leva a conclusões precisas com premissas corretas.\nAntes de se tornar investigadora, Ramona usava a dedução para entender o mundo.\nApós muitas aventuras, talvez ela considere usar a indução"
  },
  Skill_4137_Desc_0 = {
    Text = "Obtém <Posse:[Arg1]> pontos de energia de chave de prata. Escolha 1 carta do monte de puxar ou do monte de descarte para colocar na mão, tornando seu custo de aritmética 0"
  },
  Skill_4137_Desc_3 = {
    Text = "Ganhe <Posse:[Arg1]> Keyflare. Escolha um cartão do monte de compra ou da pilha de descarte e adicione-o à sua mão, reduzindo seu custo de aritmética para 0. Embaralhe 1 <DerivativeCardKeywords_4:\"Inspiração\"> no monte de compra."
  },
  Skill_4137_EffectNameList = {
    Text = "Recarregar Chave de Prata"
  },
  Skill_4137_Name = {
    Text = "Método de interpretação do mundo"
  },
  Skill_4137_OverLimitUtlSkillDesc_0 = {
    Text = "Obtém <Posse:[Arg1]> pontos de Energia da Chave de Prata. Escolha 1 carta do Mazo de robo ou Monte de descarte para colocar na Mão, fazendo seu Consumo de potência de cálculo tornar-se 0. <WeaknessIconKeywords:Fraqueza> e <VulnerabilityIconKeywords:Vulnerável> em todos os inimigos por 1 rodada, a próxima Ordem de chave liberada é ativada 2 vezes."
  },
  Skill_4137_OverLimitUtlSkillDesc_3 = {
    Text = "Obtém <Posse:[Arg1]> pontos de energia da chave de prata. Escolha 1 carta do maço de puxar ou do monte de descarte para colocar na mão, tornando seu custo de aritmética 0. Embaralhe 1 <DerivativeCardKeywords_4:\"Inspiração\"> no maço de puxar. <WeaknessIconKeywords:Fraqueza> e <VulnerabilityIconKeywords:Vulnerável> todos os inimigos por 1 turno, a próxima Ordem de chave liberada terá efeito 2 vezes."
  },
  Skill_4138_AwakerSkillBackgroundStory = {
    Text = "Ramona, aos dez anos, fez o pedido de receber treinamento de combate. \n Não era porque queria brincar de cavaleiro, mas após testemunhar os excessos e a ostentação de seu pai adotivo, a menina decidiu se preparar para uma possível falência. \n \"O salário de um guarda da rainha deve ser maior do que o da polícia, certo?\""
  },
  Skill_4138_Desc_0 = {
    Text = "Causa <Damage:[Damage:Arg1]> de dano [Arg2] vezes. Após usar, \"Espada da Rainha\" +1 dano, máx [Arg3] vezes. Ganha [Arg7] de maestria temporária"
  },
  Skill_4138_Desc_1 = {
    Text = "Causa <Damage:[Damage:Arg1]> de Dano [Arg5] vezes, ganhando [Power:Arg4] de <PowerIconKeywords:Força> Temporária por cada acerto. Após disparar, aumenta o número de acertos da \"Espada da Rainha\" em +1, até um máximo de [Arg6] vezes. Ganha [Arg7] de Domínio de área temporário. <RippleKeywords:Réplica>: Ganha Energia da Chave de Prata igual a 300% da Recarga de Chave de Prata de Ramona."
  },
  Skill_4138_Desc_3 = {
    Text = "Causa <Damage:[Damage:Arg1]> de Dano [Arg5] vezes, ganhando [Power:Arg4] de <PowerIconKeywords:Força> Temporária por cada acerto. Após disparar, aumenta o número de acertos da \"Espada da Rainha\" em +1, até um máximo de [Arg6] vezes. Ganha [Arg7] de Domínio de área temporário. <RippleKeywords:Réplica>: Ganha Energia da Chave de Prata igual a 300% da Recarga de Chave de Prata de Ramona."
  },
