  Skill_4143_Desc = {
    Text = "Causa <Damage:[Damage:Arg1]> de dano [AttackTimes:Arg2] vezes"
  },
  Skill_4144_AwakerSkillBackgroundStory = {
    Text = "Se for uma ordem do mestre, Lily pode lançar aquele grandalhão.\nEle não tem medo da dor.\nA dor é apenas força, a dor impulsiona a fúria, Lily não tem medo da dor, ele também não tem medo da dor.\nEntão, ele certamente pode ajudar o mestre a eliminar os inimigos"
  },
  Skill_4144_Desc_0 = {
    Text = "Causa <Damage:[Damage:Arg1]> de dano, ativando [Arg3]% do efeito de <IntoxicationIconKeywords:veneno> do alvo. Se ocorrer um Golpe Crítico, a taxa de ativação aumenta para [Arg4]%. Isso é considerado um \"Golpe\". Para cada pilha de <PainWord:Sofrer>, aumente o dano em 2 e remova <PainWord:Sofrer> após o uso."
  },
  Skill_4144_Desc_2 = {
    Text = "Causa <Damage:[Damage:Arg1]> de dano, ativando [Arg3]% do efeito de <IntoxicationIconKeywords:veneno> do alvo. Se ocorrer um Acerto Crítico, a taxa de ativação aumenta para [Arg4]%. Isso é considerado um \"Golpe\". Para cada pilha de <PainWord:Suportar>, aumente o dano em 2 e remova <PainWord:Suportar> após o uso. A taxa de Crítico desta carta é aumentada em 20%."
  },
  Skill_4144_Desc_3 = {
    Text = "Causa <Damage:[Damage:Arg1]> pontos de dano, desencadeando [Arg3]% do efeito de <IntoxicationIconKeywords:Envenenamento> no alvo. Se causar um Golpe Crítico, a taxa de disparo aumenta para [Arg4]%. Considerado como \"golpear\". Para cada camada de <PainWord:Paciência>, aumenta o dano em 2, removendo metade de <PainWord:Paciência> após disparar. Esta carta aumenta a Taxa de Crítico em 20%."
  },
  Skill_4144_EffectNameList = {Text = "Dano"},
  Skill_4144_Name = {
    Text = "Golpe de recompensa"
  },
  Skill_4144_PropertyNameList = {
    Text = "Poder de ataque*GrowValue1"
  },
  Skill_4144_tempBattleDesc_1 = {
    Text = "Causa <Damage:[Damage:Arg1]> pontos de dano, aciona [Arg3] % do efeito de <IntoxicationIconKeywords:Envenenamento> do alvo. Se causar crítico, a proporção de acionamento aumenta para [Arg4] %. Conta como \"Golpe\". Para cada 1 camada de <PainWord:Tolerância>, o dano aumenta em 2."
  },
  Skill_4144_tempBattleDesc_2 = {
    Text = "Causa <Damage:[Damage:Arg1]> pontos de dano, aciona [Arg3] % do efeito de <IntoxicationIconKeywords:Envenenamento> do alvo. Se causar crítico, a proporção de acionamento aumenta para [Arg4] %. Conta como \"Golpe\". Para cada 1 camada de <PainWord:Tolerância>, o dano aumenta em 2. Após jogar, remove a <PainWord:Tolerância>. A taxa de crítico desta carta aumenta em 20%."
  },
  Skill_4144_tempBattleDesc_3 = {
    Text = "Causa <Damage:[Damage:Arg1]> pontos de dano, desencadeando [Arg3]% do efeito de <IntoxicationIconKeywords:Envenenamento> no alvo. Se causar um Golpe Crítico, a taxa de disparo aumenta para [Arg4]%. Considerado como \"golpear\". Para cada camada de <PainWord:Paciência>, aumenta o dano em 2, removendo metade de <PainWord:Paciência> após disparar. Esta carta aumenta a Taxa de Crítico em 20%."
  },
  Skill_4144_tempBattleDesc_4 = {
    Text = "Causar <Damage:[Damage:Arg1]> Dano, ativar [Arg3]% do <IntoxicationIconKeywords:Envenenamento> do alvo. Se ocorrer um Golpe Crítico, a taxa de ativação aumenta para [Arg4]%. Considerado um \"golpear\". Para cada capa de <PainWord:Paciência>, aumentar o Dano em [Float:Arg6], e remover metade da <PainWord:Paciência> após o uso. Taxa de Crítico desta carta +20%."
  },
