  Skill_4151_Desc = {
    Text = "Causa <Damage:[Damage:Arg1]> de dano [AttackTimes:Arg2] vezes, ganha <Block:[Block:Arg3]> de escudo"
  },
  Skill_4152_AwakerSkillBackgroundStory = {
    Text = "Sangue derramado, corpos espalhados, dor no coração.\nPara trazer o reino de Deus de volta ao mundo, esses são sacrifícios insignificantes.\nEla só lamenta não ser a escolhida, a garota presa na gaiola"
  },
  Skill_4152_Desc_0 = {
    Text = "Escolha 1 outro desperto para ganhar <Energy:[Energy:Arg2]> pontos de loucura. <O07CardKeyWord:Ritual>: Aumente a loucura em [Arg4]/[Arg5]/[Arg6] pontos"
  },
  Skill_4152_Desc_2 = {
    Text = "Escolha 1 despertar, e ele recebe <Energy:[Energy:Arg2]> de loucura, domínio de área +[Arg3].<O07CardKeyWord:Ritual>: Receba loucura adicional de [Arg4]/[Arg5]/[Arg6] pontos"
  },
  Skill_4152_EffectNameList = {Text = "Fúria"},
  Skill_4152_Name = {Text = "Eleito"},
  Skill_4154_AwakerSkillBackgroundStory = {
    Text = "Escute, isso é o som do sino fúnebre tocando por si mesma.\nNão é uma buscadora louca, nem uma perdida sem rumo, ela apenas escolheu silenciosamente seu próprio fim.\nAs pétalas murchas dançam em seu ritual, e o vento do mar frenético chora por sua canção de lamento.\nApós aquele sino que corta o coração, o mundo mergulha brevemente em um silêncio mortal."
  },
  Skill_4154_Desc_0 = {
    Text = "Aplique [Poison:Arg1] camadas de <IntoxicationIconKeywords:veneno>, [Arg2] turnos de <WeaknessIconKeywords:fraqueza> e <VulnerabilityIconKeywords:vulnerável> a todos os inimigos"
