  Skill_4289_Desc = {
    Text = "Causa <Damage:[Damage:Arg1]> de dano [AttackTimes:Arg2] vezes, ganha [Arg3] de escudo. Antes do fim do turno do jogador, ganha escudo extra por cada carta na mão [Arg4]"
