  Skill_4313_Name = {Text = "toxina"},
  Skill_4314_AwakerSkillBackgroundStory = {
    Text = "O sangue dela fervia por causa deles, e seu cérebro borbulhava por causa deles.  \nNão importa se esses filhos de aberrante podem realizar seu desejo, não importa se eles podem sobreviver na ilusão.  \nTáias recebe cada nascimento de um filho sagrado com amor"
  },
  Skill_4314_Desc_0 = {
    Text = "[<DevouredIconKeywords:Devorar>: Faz com que outros Corpos Despertos ganhem <Energy:[Energy:Arg1]> pontos de Fúria.] Causa <Damage:[Damage:Arg2]> pontos de Dano a todos os inimigos, causando <BleedingIconKeywords:Sangramento> equivalente a [Arg3]% do dano causado, e aplica <IntoxicationIconKeywords:Envenenamento> equivalente a [Arg4]% do dano causado e ganha <RetaliateIconKeywords:Contrataque> equivalente a [Arg5]% do dano causado. Escolha 1 carta de comando não derivada na mão, coloque em sua mão [Arg7] <plural value=\"[Arg7]\" singular=\"cópia original\" plural=\"cópias originais\"> com <DepleteIconKeywords:Consumo>, <NothingnessIconKeywords:Nada> e -[Arg6] de consumo de potência de cálculo."
  },
  Skill_4314_EffectNameList = {
    Text = "Aliemus,dano,% de sangramento,% de veneno,% de contra-ataque"
  },
  Skill_4314_Name = {
    Text = "Cerimônia da Abundância"
  },
  Skill_4314_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Devorar>: Faz com que outros Corpos Despertos ganhem <Energy:[Energy:Arg1]> pontos de Fúria.] Causa <Damage:[Damage:Arg2]> pontos de Dano a todos os inimigos, causa <BleedingIconKeywords:Sangramento> equivalente a [Arg3]% do Dano, aplica <IntoxicationIconKeywords:Envenenamento> equivalente a [Arg4]% do Dano e obtém <RetaliateIconKeywords:Contrataque> equivalente a [Arg5]% do Dano. Escolhe 1 Carta de comando não derivada na mão, coloca [Arg7] Cópias Básicas com <DepleteIconKeywords:Consumo> e <NothingnessIconKeywords:Nada> anexadas na mão, reduzindo o Consumo de potência de cálculo em -[Arg6]. Durante os próximos 3 turnos, no início de cada turno, converte 1 \"embrião\" em \"Filho da santidade\"; se não houver \"embrião\", <EmbryoFusionIconKeywords:Fusão de embriões> +[Blood:Arg8], não sendo afetado pelo efeito de aumento da Fusão de embriões."
  },
