  Skill_4315_AwakerSkillBackgroundStory = {
    Text = "Proteja-me. Proteja-me. Proteja-me.\nMonstro covarde, como ela, parece vivo, mas sem consciência.\nLíquido negro forma seus servos, obedecendo ordens dia e noite"
  },
  Skill_4315_Desc_0 = {
    Text = "Lily ganha <Energy:[Energy:Arg1]> pontos de aliemus. <ExaltIconKeywords:despertar>: ao início do turno, ganha <PainWord:resistência> equivalente a 10% da vida máxima. Ao aplicar escudo, Lily aplica [Poison:Arg2] camada de <IntoxicationIconKeywords:veneno> ao inimigo com mais vida"
  },
  Skill_4315_Desc_15 = {
    Text = "Lily ganha <Energy:[Energy:Arg1]> Fúria. <ExaltIconKeywords:Despertar>: No início do turno, ganhar <PainWord:Paciência> igual a 10% da Vida máxima. Quando Lily aplicar um Escudo do personagem, infligir [Poison:Arg2] capas de <IntoxicationIconKeywords:Envenenamento> no inimigo com a Vida mais alta. Fúria Explosiva faz com que cada golpe Recebido neste turno aumente o efeito de consumo de <PainWord:Paciência> do próximo \"Golpe de recompensa\" em 40%, acumulando até 5 vezes."
