  Skill_4339_Desc_0 = {
    Text = "Aigis ganhou <Energy:[Energy:Arg1]> pontos de aliemus.<ExaltIconKeywords:despertar>: Após usar um cartão, Aigis impõe [Arg2] rodadas a todos os inimigos <VulnerabilityIconKeywords:vulnerável>"
