  Skill_4373_AwakerSkillBackgroundStory = {
    Text = "Suas nadadeiras dianteiras podem cortar o caminho, e a cauda pode abrir um porto.\nSem ninguém para lutar, a baleia gigante dorme no caos, confiando o planeta às novas criaturas"
  },
  Skill_4373_BattleDesc_0 = {
    Text = "Dispersa o estado de <WeaknessIconKeywords:fraqueza> de si mesmo. Causa <Damage:[Damage:Arg1]> de dano a todos os inimigos [Arg3] vezes. Cada vez que jogar um \"Ataque\" nesta batalha, aumenta o dano em [Arg2]."
  },
  Skill_4373_BattleDesc_3 = {
    Text = "Dissipa o estado de <WeaknessIconKeywords:fraqueza> de si mesmo. Causa <Damage:[Damage:Arg1]> de dano a todos os inimigos [Arg3] vezes. Cada vez que jogar 1 \"golpear\" nesta batalha, aumenta o dano em [Arg2]. Coloque 2 \"golpear\" adicionais com <DepleteIconKeywords:Consumo> e <NothingnessIconKeywords:Nada> na sua mão."
  },
  Skill_4373_Desc_0 = {
    Text = "Dispersa o estado de <WeaknessIconKeywords:fraqueza>. Causa <Damage:[Damage:Arg1]> de dano a todos os inimigos. Cada vez que jogar um \"Ataque\" nesta batalha, aumenta o dano em [Arg2]"
  },
  Skill_4373_Desc_15 = {
    Text = "Dispels its own <WeaknessIconKeywords:Fraqueza> state. Deals <Damage:[Damage:Arg1]> dano to all enemies [Arg3] times. For each \"Strike\" played in this battle, the damage increases by [Arg2]. Place 2 \"Strikes\" with <DepleteIconKeywords:Exausto> and <NothingnessIconKeywords:Ilusão> into hand."
  },
  Skill_4373_Desc_3 = {
