  Skill_4459_Name = {Text = "Convulsão"},
  Skill_4460_AwakerSkillBackgroundStory = {
    Text = "Pai Deus chegou em seu sonho, trazendo a ele uma orientação: \n\n \"Quando o céu for dividido entre o sol e a lua, vá sozinho para a floresta e caminhe quinhentos passos para leste. No calor da escuridão, está enterrado meu último osso. \n\n Leve, meu Executor, mas lembre-se. O sangue da carne deve ser pago com carne, a vida deve ser preenchida com vida.\" \n\n Ele desenterrou o tablete gravado com símbolos misteriosos, oferecendo seu sangue e ossos a eles, em troca de uma centelha de esperança para os que sofrem."
  },
