  Skill_4575_AwakerSkillBackgroundStory = {
    Text = "Isso é uma ruína antiga feita de corais.\nNo início, era apenas um brilho branco ondulando na água.\nDepois, surgiram degraus altos, distorções, colunas imponentes…\nBang! Quando tudo parou, a Arte Perdida finalmente revelou-se no fundo do mar.\nEla deve ir ao encontro da arte."
  },
  Skill_4575_BattleDesc_0 = {
    Text = "Ganha <Block:[Block:Arg1]> pontos de escudo. Causa <Damage:[Damage:Arg2]> de dano a todos os inimigos, cada ponto de escudo aumenta o dano em [Arg3] pontos, esta habilidade também recebe um bônus de [Arg4]% de taxa de crítico e dano crítico. Em batalhas contra chefes, esta habilidade causa 1 dano adicional."
  },
  Skill_4575_BattleDesc_3 = {
