  Skill_4576_AwakerSkillBackgroundStory = {
    Text = "Entregue-me sua cabeça.\nCom certeza se tornará uma das minhas coleções preciosas, à deriva no mar das dimensões.\nA Caçadora de Crânios sorriu de maneira despreocupada.\n\"Se você tiver sorte, pode até ficar ao meu lado como os outros.\""
  },
  Skill_4576_BattleDesc_0 = {
    Text = "Causa <Damage:[Damage:Arg1]> de dano ao inimigo com menos vida, o poder tem um efeito de 5 vezes em \"Golpe de pescoço\". Quando Daffodil mata um inimigo de qualquer forma, o dano base de \"Golpe de pescoço\" aumenta permanentemente em 25% nesta fase (atualmente [Arg3] vezes). <TransitionIconKeywords:salto>: muda para causar <Damage:[Damage:Arg2]> de dano ao inimigo com mais vida."
  },
  Skill_4576_Desc_0 = {
    Text = "Causa <Damage:[Damage:Arg1]> de dano ao inimigo com menos vida, e a força tem um efeito 5 vezes maior em \"Golpe de pescoço\". Quando Daffodil elimina um inimigo de qualquer forma, o dano básico de \"Golpe de pescoço\" aumenta permanentemente em 25% nesta fase. <TransitionIconKeywords:salto>: Altera para causar <Damage:[Damage:Arg2]> de dano ao inimigo com mais vida."
  },
  Skill_4576_EffectNameList = {
