  Skill_4579_AwakerSkillBackgroundStory = {
    Text = "O mago disse: \"Os pagãos são numerosos\n e nós, em Levante, parecemos fracos. \n Irmão Uvhash, toque sua trombeta, \n e lute como um louco.\" \n O guerreiro respondeu: \"Não há pagãos aqui. \n Todos vocês serão mortos por mim, os mortos não têm distinção de etnia ou crença. \n Quando os corpos cobrem o vale e se espalham pelo topo da montanha, \n será a minha oferenda ao Ode ao Sangue e à Areia.\""
  },
  Skill_4579_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Devorar>: O dano de \"Ode ao Sangue e à Areia\" liberado posteriormente nesta batalha aumenta em [Arg4] pontos, e o multiplicador de força aumenta em [Arg3] vezes.] Causa <Damage:[Damage:Arg1]> pontos de dano a todos os inimigos. <PowerIconKeywords:Força> tem um efeito de [Arg2] vezes em \"Ode ao Sangue e à Areia\". Uvhash ganha <Energy:[Energy:Arg5]> pontos de Fúria."
  },
  Skill_4579_Desc_0 = {
    Text = "[<DevouredIconKeywords:Devorar>: O dano da \"Ode ao Sangue e à Areia\" lançado posteriormente nesta batalha aumenta em [Arg4] pontos, e o multiplicador de força aumenta em [Arg3] vezes.] Causa <Damage:[Damage:Arg1]> pontos de dano a todos os inimigos. <PowerIconKeywords:Força> tem um efeito de [Arg2] vezes na \"Ode ao Sangue e à Areia\". Ganha uma quantidade de fúria equivalente a 2 vezes a regeneração de fúria de Uvhash."
  },
  Skill_4579_EffectNameList = {
    Text = "Dano, Aumento de Dano"
  },
  Skill_4579_Name = {
    Text = "Ode ao Sangue e à Areia"
  },
  Skill_4579_OverLimitUtlSkillDesc = {
    Text = "[<DevouredIconKeywords:Devorar>: O dano causado pela \"Ode ao Sangue e à Areia\" liberada posteriormente nesta batalha aumenta em [Arg4] pontos, e o multiplicador de força aumenta em [Arg3] vezes.] Causa <Damage:[Damage:Arg1]> pontos de dano a todos os inimigos. <PowerIconKeywords:Força> tem um efeito de [Arg2] vezes em \"Ode ao Sangue e à Areia\". Uvhash ganha <Energy:[Energy:Arg5]> pontos de fúria. Preenche a mão com \"Grite, sangue!\" que adiciona nada e exaustão. O número de danos de Uvhash neste turno aumenta em 1."
  },
