  Skill_4581_AwakerSkillBackgroundStory = {
    Text = "Abaixo da catedral há um espaço oculto.\n\nO bispo está de joelhos diante do tablete, recitando os murmúrios deixados desde o início da criação.\n\nAs runas esquecidas pelo tempo emitem uma luz de resposta, revelando uma enorme sombra em resposta à vontade do bispo, concedendo a \"bênção\" do Criador àqueles que estão sob seu brilho."
  },
  Skill_4581_Desc_0 = {
    Text = "[<DevouredIconKeywords:Devorar>: Ganhe [Power:Arg1] pontos temporários de <PowerIconKeywords:Poder> e uma Taxa crítica temporária de +[Arg4]%.]Ganhe <Block:[Block:Arg2]> Escudo. <VulnerabilityIconKeywords:Vulnerável> todos os inimigos por 1 turno. Até o próximo turno, quando for Atacado, [Arg3]% do Dano é convertido em recuperação da Fornalha Crimsom."
  },
  Skill_4581_Desc_3 = {
    Text = "[<DevouredIconKeywords:Devorar>: Ganhe [Power:Arg1] pontos temporários de <PowerIconKeywords:força>, taxa de crítico temporária +[Arg4]%.] Obtenha <Block:[Block:Arg2]> pontos de escudo. Aplique <VulnerabilityIconKeywords:Vulnerável> a todos os inimigos por 1 turno. Até o início da próxima rodada, ao sofrer danos de ataque, converta [Arg3]% do dano em recuperação na Fornalha Carmesim. Salvador ganha [Arg5]% de dano crítico temporário."
  },
  Skill_4581_EffectNameList = {
    Text = "Força temporária, escudo, quantidade de conversão da fornalha carmesim"
  },
  Skill_4581_Name = {
    Text = "Bênção do Criador"
  },
  Skill_4581_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Devorar>: Obtém [Power:Arg1] pontos de <PowerIconKeywords:Força> Temporária, Taxa de Crítico Temporária +[Arg4]%.] Obtém <Block:[Block:Arg2]> pontos de Escudo. <VulnerabilityIconKeywords:Vulnerável> em todos os inimigos por 1 rodada. Até o início do próximo turno, ao receber um ATQ, converte [Arg6]% do Dano em recuperação do Forno Carmesim. Faz com que o \"Golpe Básico\" e \"Sofrimento a ser eliminado\" de Salvador recebam adicionalmente 100% de bônus de Força. Nesta exploração, o limite máximo do Forno Carmesim aumenta 2% da Vida máxima, até no máximo 10%."
  },
  Skill_4581_OverLimitUtlSkillDesc_3 = {
    Text = "[<DevouredIconKeywords:Devorar>: Ganhe [Power:Arg1] pontos temporários <PowerIconKeywords:força>, a taxa de crítico temporária aumenta em +[Arg4]%.] Obtenha <Block:[Block:Arg2]> pontos de escudo. <VulnerabilityIconKeywords:Vulnerável> todos os inimigos por 1 turno. Até o início do próximo turno, ao sofrer danos, converta [Arg6]% do dano em quantidade de recuperação da fornalha carmesim. Salvador ganha [Arg5]% de dano crítico temporário. Faz com que \"Golpe Básico\" e \"Sofrimento a ser eliminado\" de Salvador recebam um bônus adicional de 100% de força. Durante esta exploração, o limite da fornalha carmesim é aumentado em 2% da vida máxima, com um aumento máximo de 10%."
  },
