  Skill_4615_AwakerSkillBackgroundStory = {
    Text = "Faint é imperfeita.  \nFaint é perigosa.  \nFaint é amaldiçoada.  \nFaint é a mais enigmática e colorida das cores vindas das estrelas"
  },
  Skill_4615_BattleDesc_15 = {
    Text = "Faint ganha <Energy:[Energy:Arg1]> Fúria. <ExaltIconKeywords:Despertar>: Imediatamente e permanentemente <TouquKeywords:rouba> [Arg4] <PowerIconKeywords:STR> de todos os inimigos. Ganha [Counterattack:Arg3] <plural value=\"[Counterattack:Arg3]\" singular=\"capa\" plural=\"capas\"> de <RetaliateIconKeywords:Contrataque>. A taxa de decaimento da Resistência à Morte nesta batalha é reduzida de 50% para 45%. Quando Faint dispara uma carta, <TouquKeywords:rouba> [Arg2] <PowerIconKeywords:STR> de todos os inimigos. No fim do turno, causa <RealDamage:Dano Fixo> igual a 50% do <RetaliateIconKeywords:Contrataque> de Faint."
  },
  Skill_4615_Desc_0 = {
