  Skill_4654_Desc = {
    Text = "Obtenha [Arg1] pontos de escudo. O escudo de lodo convocado por Lily pode e só pode resistir a uma mordida do cão infernal. Será que... não dói mesmo?"
  },
  Skill_4654_Name = {
