  },
  Skill_4655_AwakerSkillBackgroundStory = {
    Text = "O oceano é profundo e sereno, carregando o desejo de viver e o medo da morte.\n Mas há sempre quem queira preencher o mar com risadas e brincadeiras — quando Aurita faz tal convite, a sensação de \"por que não brincar com ela\" sempre surge no coração, permitindo que a simples alegria encha o peito."
  },
  Skill_4655_Desc_0 = {
    Text = "Causar <Damage:[Damage:Arg1]> pontos de dano. exausto no máximo 10 cartas de \"divisão glandular\" dos baralhos de puxar e de descarte, causando dano adicional uma vez por carta. coloca 2 cartas de \"divisão glandular\" na mão. aumenta o dano causado por \"aurita\" em [Arg2] pontos nesta batalha"
  },
  Skill_4655_Desc_2 = {
    Text = "Causa <Damage:[Damage:Arg1]> pontos de <PunctureDamagewords:dano perfurante>. Exausto no máximo 10 cartas de \"Divisão de glândulas\" dos baralhos de puxar e de descarte, causando dano adicional uma vez por carta. Coloque 2 cartas de \"Divisão de glândulas\" na mão. Aumenta o dano causado por \"Aurita\" em [Arg2] pontos nesta batalha."
  },
  Skill_4655_EffectNameList = {
    Text = "Dano, Aumento de Dano Posterior"
  },
  Skill_4655_Name = {
    Text = "Mar Agitado"
  },
  Skill_4655_OverLimitUtlSkillDesc_0 = {
    Text = "Causa <Damage:[Damage:Arg1]> pontos de Dano. Consome até 10 cartas de \"Divisão de glândulas\" do Mazo de robo e do Monte de descarte, cada uma causa 1 vez adicional de Dano. Coloca 2 cartas de \"Divisão de glândulas\" na mão. Aumenta o Dano causado por \"Aurita\" no restante desta batalha em [Arg2] pontos. Obtém [Power:Arg2] pontos de <PowerIconKeywords:Força> e [TentaclePower:Arg2] pontos de <TentacleInjurieIconKeywords:Dano de tentáculo>, e nas próximas 5 vezes que \"Divisão de glândulas\" for jogada, compra 1 carta."
  },
  Skill_4655_OverLimitUtlSkillDesc_2 = {
    Text = "Causa <Damage:[Damage:Arg1]> pontos de <PunctureDamagewords:dano perfurante>. Exausto no máximo 10 cartas de \"Divisão de glândulas\" dos baralhos de puxar e de descarte, causando dano adicional uma vez por carta. Coloque 2 cartas de \"Divisão de glândulas\" na mão. Aumenta o dano causado por \"Aurita\" em [Arg2] pontos nesta batalha. Ganhe [Power:Arg2] pontos de <PowerIconKeywords:força> e [TentaclePower:Arg2] pontos <TentacleInjurieIconKeywords:dano de tentáculo>, sempre que jogar \"Divisão de glândulas\" nas próximas 5 vezes, compre 1 carta."
  },
