  Skill_4658_AwakerSkillBackgroundStory = {
    Text = "As mãos de Casiah estavam vazias;\nO chapéu de Casiah estava vazio;\nO peito de Casiah estava vazio.\nA vazia Casiah carregava uma alegria vazia, realizando uma performance vazia na celebração vazia"
  },
  Skill_4658_Desc_0 = {
    Text = "Casiah ganhou <Energy:[Energy:Arg1]> pontos de aliêmus, <ExaltIconKeywords:despertar>: Casiah ganha [Power:Arg2] pontos de <PowerIconKeywords:poder> temporários ao jogar 1 cartão"
  },
  Skill_4658_Desc_15 = {
    Text = "Casiah obtém <Energy:[Energy:Arg1]> Fúria. <ExaltIconKeywords:Despertar>: Cada vez que Casiah Dispara 1 Carta, obtém [Power:Arg2] <PowerIconKeywords:FOR> Temporária. Todos os Corpos Despertos também ativam este efeito ao Disparar \"golpear\"."
