  Skill_4659_tempBattleDesc_2 = {
    Text = "Obtém <Block:[Block:Arg1]> pontos de escudo. Obtém <Energy:[Energy:Arg2]> pontos de Fúria. A próxima\"Lâmina Indomável\"deste turno ativa 2 vezes."
  },
  Skill_4660_AwakerSkillBackgroundStory = {
    Text = "Um, dois, um, dois...\nEla levanta a bandeja e se move com um ritmo leve entre a multidão.\nOs convidados não param de beber e cantar, ela não para de servir e sorrir.\nAqui tudo é dourado. O salão dourado, o vinho dourado, e as saias douradas.\nKaren gosta de dourado. Ela exibe seu sorriso característico, praticado inúmeras vezes.\n\"Convidado, aproveite a refeição — !!\""
  },
  Skill_4660_Desc_0 = {
    Text = "Remova <SlowIconKeywords:Slowness> de todos os cartões na mão. Restaure <Heal:[Heal:Arg1]> pontos de Vida. Adicione 1 <DerivativeCardKeywords_42:\"Culinária Maravilhosa\"> à sua mão. Aplique [Poison:Arg2] camadas de <IntoxicationIconKeywords:Poison> a todos os inimigos."
  },
  Skill_4660_Desc_3 = {
    Text = "Remova o estado <SlowIconKeywords:Devagar> de todos os cartões na mão. Restaure <Heal:[Heal:Arg1]> pontos de Vida. Adicione 1 <DerivativeCardKeywords_43:\"Culinária Maravilhosa\"> à sua mão. Aplique [Poison:Arg2] camadas de <IntoxicationIconKeywords:Veneno> a todos os inimigos."
  },
  Skill_4660_EffectNameList = {
    Text = "Recuperação, envenenamento"
  },
  Skill_4660_Name = {
    Text = "Aproveite sua refeição, senhor!"
  },
  Skill_4660_OverLimitUtlSkillDesc_0 = {
    Text = "Remove o Estado <SlowIconKeywords:Desaceleração> de todas as cartas na Mão. Recupera <Heal:[Heal:Arg1]> pontos de Vida. Coloca 1 carta de <DerivativeCardKeywords_43:\"Prato Maravilhoso\"> na Mão. Aplica [Poison:Arg2] camadas de <IntoxicationIconKeywords:Envenenamento> a todos os inimigos. Embaralha 1 carta de <DerivativeCardKeywords_42:\"Prato Maravilhoso\"> no Mazo de robo e 1 no Monte de descarte."
  },
  Skill_4660_OverLimitUtlSkillDesc_3 = {
    Text = "Remova o estado de <SlowIconKeywords:lento> de todas as cartas na mão. Recupere <Heal:[Heal:Arg1]> pontos de vida. Adicione 1 carta <DerivativeCardKeywords_43:\"Prato Maravilhoso\"> à mão. Aplique [Poison:Arg2] camadas de <IntoxicationIconKeywords:envenenamento> a todos os inimigos. Embaralhe 1 de <DerivativeCardKeywords_43:\"Prato Maravilhoso\"> na pilha de puxar e na pilha de descarte."
  },
