  },
  Skill_4662_AwakerSkillBackgroundStory = {
    Text = "Admiravam sua beleza e charme, mas ninguém dava importância a um botão de flor.\nNo campo, o botão oscilava, seu futuro decidido por outros, usado como moeda de troca para a ascensão dos jardineiros.\nSó quando ela floresceu diante da coroa, perceberam que estavam sangrando pelos espinhos"
  },
  Skill_4662_BattleDesc_0 = {
    Text = "Causar aleatoriamente <Damage:[Damage:Arg1]> dano [Arg3] vezes. No final do turno, restaure <Heal:[Heal:Arg2]> hp."
