  },
  Skill_4663_AwakerSkillBackgroundStory = {
    Text = "O frio mecânico substituiu o coração, o óleo dentro dos tubos hidráulicos substituiu o sangue. Ela deveria ser fria, racional, agir de acordo com as ordens.\n Mas, uma vontade externa se movia silenciosamente dentro de seu corpo. Ele não precisava de sangue, não precisava de temperatura, podia queimar apenas com sua própria malícia não humana. Ele disse: submeta-se, criatura humilde e fraca, e então destrua-se em minha esfera elétrica ardente."
  },
  Skill_4663_BattleDesc_0 = {
    Text = "Ganha [Power:Arg1] pontos temporários de <PowerIconKeywords:força>. Ganha <Posse:[Arg2]> pontos de energia da chave de prata. Dissipe seu estado <WeaknessIconKeywords:fraqueza>. Sempre que 1 carta entrar no <DimensionalSpaceIconKeywords:Espaço Hiperdimensional>, transforme-se em <DerivativeCardKeywords_14:\"Armadura Mecânica - Recolher\">."
  },
  Skill_4663_BattleDesc_1 = {
    Text = "Ganha [Power:Arg1] pontos temporários de <PowerIconKeywords:força>. Ganha <Posse:[Arg2]> pontos de energia da chave de prata. Dissipe seu estado <WeaknessIconKeywords:fraqueza>. Coloque 1 carta de \"golpear\" com <DepleteIconKeywords:consumo> anexada de Erica na mão. Sempre que 1 carta entrar no <DimensionalSpaceIconKeywords:Espaço Hiperdimensional>, transforme-se em <DerivativeCardKeywords_14:\"Armadura Mecânica - Recolher\">."
  },
  Skill_4663_Desc_0 = {
    Text = "Ganha [Power:Arg1] pontos de <PowerIconKeywords:força> temporária. Obtém energia da chave de prata equivalente ao recarregar a chave de prata de Erica. Dissipe seu estado de <WeaknessIconKeywords:fraqueza>. Sempre que 1 carta entrar no <DimensionalSpaceIconKeywords:Espaço Hiperdimensional>, transforme-se em <DerivativeCardKeywords_14:\"Arma Mecânica - Recolher\">."
  },
  Skill_4663_Desc_1 = {
    Text = "Ganha [Power:Arg1] pontos temporários de <PowerIconKeywords:força>. Ganha energia da chave de prata equivalente à recarga da chave de prata de Erica. Dissipe seu estado <WeaknessIconKeywords:fraqueza>. Coloque 1 carta de \"golpear\" com <DepleteIconKeywords:consumo> anexada a Erica na mão. Sempre que 1 carta entrar no <DimensionalSpaceIconKeywords:Espaço Hiperdimensional>, transforme-se em <DerivativeCardKeywords_14:\"Armadura Mecânica - Recolher\">."
  },
