  },
  Skill_4664_AwakerSkillBackgroundStory = {
    Text = "A praga invisível se espalha silenciosamente, trazendo dor e loucura sem fim. \n\nO bispo não consegue dormir à noite, profundamente angustiado por não poder aliviar o sofrimento das pessoas. \n\n\"Misericordioso Criador, salve-os, eu estou disposto a suportar toda a dor e tristeza por eles.\" \n\nEntão, o Pai Deus concedeu-lhe a \"bênção\", permitindo que ele segurasse o tablete gravado com a Palavra de Deus, realizando ações de alívio do sofrimento e dificuldades."
  },
  Skill_4664_Desc_0 = {
    Text = "Salvador ganhou <Energy:[Energy:Arg1]> pontos de aliemus. <ExaltIconKeywords:despertar>: Coloque 1 <B02AFKeyWord:amor é proteger> na mão. Ao final do turno, ganhe [Power:Arg2] pontos de <PowerIconKeywords:poder>"
  },
  Skill_4664_Desc_15 = {
    Text = "Salvador ganha <Energy:[Energy:Arg1]> Fúria. <ExaltIconKeywords:Despertar>: Coloque 1 <B02AFKeyWord:Protegido pelo amor benevolente> na mão. No fim do turno, ganhe [Power:Arg2] <PowerIconKeywords:FOR>. Forno Carmesim acumulado por \"Bênção do Criador\" e \"sangue e ossos abençoados\" +25%, e quando \"Exorcismo\" é selecionado para \"Sofrimento a ser eliminado,\" cada 1% de Vida máxima consumida do Forno Carmesim concede +5% Dano Final."
  },
