  Skill_4694_AwakerSkillBackgroundStory = {
    Text = "Na sombria prisão de Newgate, o óleo de cera, abundante em Londinium, é também uma raridade. \n Sendo raro, deve ser usado em momentos cruciais, como na punição, aplicado na pele de crianças desobedientes. \n Não é um óleo de cera especial, e quando pinga, é acompanhado de gritos de dor, mas para os ouvidos da menina, soa como um poema elegante."
  },
  Skill_4694_BattleDesc_0 = {
    Text = "Ganha [Counterattack:Arg2] camadas de <RetaliateIconKeywords:contrataque>. Reduza temporariamente [Exhaustion:Arg1] pontos de <ExhaustionIconKeywords:força> de todos os inimigos, ganhando [Power:Arg1] pontos de <PowerIconKeywords:força temporária> para cada inimigo. Remova o estado de <RetaliateIconKeywords:contrataque> de todos os inimigos."
