  Skill_4694_BattleDesc_2 = {
    Text = "Ganha [Counterattack:Arg2] camadas de <RetaliateIconKeywords:contrataque>. Reduz temporariamente [Exhaustion:Arg1] pontos de <ExhaustionIconKeywords:força> de todos os inimigos, ganhando [Power:Arg1] pontos de <PowerIconKeywords:força temporária> para cada inimigo. Remove o estado de <RetaliateIconKeywords:contrataque> de todos os inimigos. Ganha <Energy:[Energy:Arg3]> pontos de fúria."
  },
  Skill_4694_Desc_0 = {
    Text = "Ganhe [Counterattack:Arg2] camadas de <RetaliateIconKeywords:counter>. <TouquKeywords:steal> [Arg1] <PowerIconKeywords:str> de todos os inimigos e remova seu estado de <RetaliateIconKeywords:counter>."
