  },
  Skill_4698_Name = {Text = "Oração"},
  Skill_4701_AwakerSkillBackgroundStory = {
    Text = "Isso são embriões distorcidos, são sementes malignas.\nÉ o batimento cardíaco pulsante, é o pulso intenso, é o despreço entre carne e sangue, um destino entrelaçado.\nO ser transformado não possui liberdade de escolha, apenas pode permitir que o errado se desenvolva"
  },
  Skill_4701_Desc_0 = {
    Text = "Murphy ganha <Energy:[Energy:Arg1]> pontos de fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: ganhe 1 tentáculo, após Murphy disparar uma carta, ganhe 1 tentáculo temporário que ignora o limite de tentáculos e o equivalente a 1 consumo de potência de cálculo da Chave de Prata, podendo ativar no máximo 3 vezes por turno."
  },
  Skill_4701_Desc_15 = {
    Text = "Murphy ganha <Energy:[Energy:Arg1]> Fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: Ganha 1 tentáculo. Depois que Murphy Disparar uma carta, ganha 1 Tentáculo Temporário ignorando o Limite de tentáculos, mais Recarregar Chave de Prata igual a 1 Consumo de potência de cálculo, até 3 vezes por turno. A primeira \"Corrente Inversa de Parafuso\" e \"Criação da Santa Mulher\" Disparadas a cada turno têm sua contagem de Dano e ganho de Poder de cálculo dobrados respectivamente."
  },
