  Skill_4745_tempOverLimitUtlSkillDesc_1 = {
    Text = "Erica obtém [Arg4]% de Taxa de Crítico Temporária e Dano crítico. Obtém <Block:[Block:Arg6]> pontos de Escudo. Causa <Damage:[Damage:Arg5]> de Dano a todos os inimigos e aplica [Arg3] camadas de <WeaknessIconKeywords:Fraqueza> e <VulnerabilityIconKeywords:Vulnerável>. O \"Golpe Básico\" de Erica causa 1 Dano adicional e a \"Defesa Básica\" obtém 1 Escudo adicional, durante 3 turnos."
  },
  Skill_4745_tempOverLimitUtlSkillDesc_2 = {
    Text = "Erika obtém [Arg4]% de Taxa de Crítico e Dano Crítico temporários. Obtém <Block:[Block:Arg6]> pontos de escudo. Causa <Damage:[Damage:Arg5]> de dano a todos os inimigos e aplica [Arg3] camada(s) de <WeaknessIconKeywords:Fraqueza> e <VulnerabilityIconKeywords:Vulnerabilidade>. Esta habilidade recebe [Arg7] vez(es) o bônus de <PowerIconKeywords:Força> e <AlertIconKeywords:Vigilância> adicional. O \"Ataque Básico\" de Erika causa 1 instância de dano adicional, e a \"Defesa Básica\" obtém 1 instância de escudo adicional, durante 3 rodadas."
  },
  Skill_4745_tempOverLimitUtlSkillDesc_3 = {
    Text = "Erika obtém [Arg4]% de Taxa de Crítico e Dano Crítico temporários. Obtém <Block:[Block:Arg6]> pontos de escudo. Causa <Damage:[Damage:Arg5]> de dano a todos os inimigos e aplica [Arg3] camada(s) de <WeaknessIconKeywords:Fraqueza> e <VulnerabilityIconKeywords:Vulnerabilidade>. Esta habilidade recebe [Arg7] vez(es) o bônus de <PowerIconKeywords:Força> e <AlertIconKeywords:Vigilância> adicional, e os bônus de Força e Vigilância de usos subsequentes aumentam em 1 vez adicional. O \"Ataque Básico\" de Erika causa 1 instância de dano adicional, e a \"Defesa Básica\" obtém 1 instância de escudo adicional, durante 3 rodadas."
  },
  Skill_4746_Desc = {
    Text = "Reduza o [Arg2] STR Temporário de todos os inimigos e coloque um <DerivativeCardKeywords_28:Sintoma:\"Colapso\"> em sua mão. \"Dói? Tão triste... Apenas chore!\""
