  Skill_47484_Name = {
    Text = "Inspiração avançada"
  },
  Skill_4748_AwakerSkillBackgroundStory = {
    Text = "As crianças vão lentamente perceber a essência dos contos de fadas e entender a fábula por trás dos mitos. Na linguagem humana, esse processo é chamado de \"crescer\".\n Mas também há crianças que passam a acreditar cada vez mais nas histórias de ninar, e que teimosamente acreditam que realmente existe uma ponte do arco-íris no céu e que civilizações realmente afundaram no Mar Profundo.\n Aurita gosta dessas histórias e quer compartilhar essa alegria com mais amigos."
  },
  Skill_4748_Desc_0 = {
    Text = "<TentacleInjurieIconKeywords:dano de tentáculo> +[TentaclePower:Arg1]. Descarte todas as cartas da mão e compre a mesma quantidade de cartas. Adicione 1 \"Divisão Glandular\" ao descarte."
  },
  Skill_4748_Desc_1 = {
    Text = "<TentacleInjurieIconKeywords:dano de tentáculo> +[TentaclePower:Arg1]. Descarte todas as cartas da mão e compre a mesma quantidade +1 de cartas. Coloque 1 carta \"Divisão Glandular\" no descarte."
  },
  Skill_4748_EffectNameList = {
