  },
  Skill_4750_AwakerSkillBackgroundStory = {
    Text = "Conceba, nasça, reproduza. \n Na realidade que se dissolve gradualmente, no mundo que se torna sombrio, no vazio que está prestes a renascer. \n A sua existência é o fruto do sacrifício da mãe, é a causa da continuidade da mãe. \n Ó Filho da santidade, renasça no novo mundo — renasça naquele novo mundo imaculado, que dissipou todo medo."
  },
  Skill_4750_Desc_0 = {
    Text = "Táias ganha <Energy:[Energy:Arg1]> pontos de alienação. <ExaltIconKeywords:despertar> da gnose: recebe imediatamente 1 carta de <DerivativeCardKeywords_10:Filho Sagrado>. Cada vez que uma chave for liberada, transforme um embrião em sua mão em <DerivativeCardKeywords_10:Filho Sagrado>"
  },
  Skill_4750_Desc_15 = {
    Text = "Thais ganha <Energy:[Energy:Arg1]> Fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: Ganhe imediatamente 1 <DerivativeCardKeywords_10:Filho da santidade>. Sempre que uma Ordem de chave for liberada, transforme 1 embrião na mão em 1 <DerivativeCardKeywords_10:Filho da santidade>. \"Cerimônia da Abundância\" adicionalmente coloca 1 cópia extra na sua mão."
  },
  Skill_4750_EffectNameList = {Text = "Fúria"},
  Skill_4750_Name = {Text = "ver a mãe"},
  Skill_47516_Desc_1 = {
    Text = "<PVPWeaponKeywords:wheel of destiny>: No final do turno, descarte [Arg1] cartas de outros despertadores. Se o descarte for bem-sucedido, compre [Arg2] cartas."
  },
  Skill_47516_Name_1 = {
