  },
  Skill_4751_AwakerSkillBackgroundStory = {
    Text = "Não pisque, olhe atentamente, o momento mágico chegou;\nLuvas brancas, chapéu preto, eu crio cartas coloridas do nada.\nTão glamourosas quanto fitas, tão deslumbrantes quanto lantejoulas,\nesta apresentação brilhante e louca, você com certeza não vai conseguir adivinhar!"
  },
  Skill_4751_Desc_0 = {
