  Skill_4769_AwakerSkillBackgroundStory = {
    Text = "Sua capital é uma ruína em expansão.\nSonhos morrem aqui, mas as ruínas não sabem disso. Elas apenas continuam a crescer.\nO mundo já a esqueceu"
  },
  Skill_4769_Desc_0 = {
    Text = "Receba <Block:[Block:Arg1]> pontos de escudo e [Counterattack:Arg2] camadas de <RetaliateIconKeywords:contrataque>, o próximo efeito de salto neste turno será ativado com certeza. Pode optar por consumir camadas de <DreamGuide:guia de sonhos> para ativar <JingjinvwangKeywords1:Contra-ataque de sono profundo> ou <JingjinvwangKeywords2:Ecos de sussurros>, se as camadas de <DreamGuide:guia de sonhos> forem insuficientes (menos de 5 camadas), ganhe 1 camada de <DreamGuide:guia de sonhos>."
