  },
  Skill_4769_tempBattleDesc_2 = {
    Text = "Obtém <Block:[Block:Arg1]> pontos de escudo e [Counterattack:Arg2] camada(s) de <RetaliateIconKeywords:Contra-ataque>. O próximo efeito de Salto deste turno é garantido. Sem consumir Guia Onírico, aciona simultaneamente\"<JingjinvwangKeywords3:Pulso Hipnótico>\",\"<JingjinvwangKeywords1:Contra-ataque de Sono Profundo>\"e\"<JingjinvwangKeywords2:Eco de Delírio>\". As próximas 2 cartas de comando jogadas por Wanda ativam 1 vez adicional."
