  Skill_4804_AwakerSkillBackgroundStory = {
    Text = "As chamas se propagam, refletindo o céu do teatro em um verde esmeralda, como a água de um lago claro e tranquilo pela manhã. \n Quantas pessoas vieram em busca dessa silhueta esmeralda, e quantas ignoraram a dança fluida e cheia de força, apenas vendo os braços de jade que se revelavam vagamente e a paisagem imaginada sob a saia. \n E o dançarino permanecia ali, imóvel como se estivesse congelado, em uma postura de morte prestes a ser devorada pela Chama Verde."
  },
  Skill_4804_Desc_0 = {
    Text = "Liz ganha <Energy:[Energy:Arg1]> pontos de Aliemus. <ExaltIconKeywords:Gnosis Rouse>: Para cada [Arg2] dano causado, Liz coloca 1 cartão com <DepleteIconKeywords:Exhaust> de <DerivativeCardKeywords_18:\"Green Flame\"> em sua mão, ativando no máximo 3 vezes a cada turno."
