  Skill_4821_AwakerSkillBackgroundStory = {
    Text = "O labirinto dela leva a cada canto do mundo.\nHá entradas na floresta densa, no subterrâneo da biblioteca e nas profundezas do mar.\nFoi com a ajuda daqueles infelizes que se perderam no labirinto que ela conseguiu esboçar a aparência do mundo.\nOs viajantes se perdem em passagens que se entrelaçam constantemente, enquanto ela se perde em histórias que mudam continuamente.\nEla sabe de tudo, mas não consegue mais sair do labirinto nem por um passo."
  },
  Skill_4821_Desc_0 = {
    Text = "Causa <Damage:[Damage:Arg1]> de dano e o mesmo de<IntoxicationIconKeywords:veneno>. Ao ativar devorar, coloca \"Giro Pálido\" da pilha de descarte na mão"
  },
  Skill_4821_Desc_3 = {
    Text = "Causa <Damage:[Damage:Arg1]> de Dano e aplica o mesmo de <IntoxicationIconKeywords:Envenenamento>. <EmbryoFusionIconKeywords:Fusão de embriões> +[Blood:Arg2]. Ao ativar Devorar, coloca \"Remoinho pálido\" do Monte de descarte na Mão."
  },
  Skill_4821_EffectNameList_0 = {Text = "Dano"},
