  Skill_4822_AwakerSkillBackgroundStory = {
    Text = "Na errância sem fim, Tinct já esqueceu o nome da sua terra natal.\nAo longo dos longos anos, o universo já esqueceu o nome daquele planeta morto.\nEle, assim como inúmeros planetas dissolvidos e abandonados, é coletivamente chamado de \"Estrela Desolada\".\nSua canção pode ser o último resquício sonoro daquele planeta além da realidade."
  },
  Skill_4822_Desc_0 = {
    Text = "A Tinta ganha <Energy:[Energy:Arg1]> pontos de loucura, <ExaltIconKeywords:despertar da gnose>: Aumenta o dano base do \"golpe\" da Tinta em [Arg2]%; todas as cartas da Tinta ganham 1 efeito aleatório, que será removido ao final da batalha"
  },
  Skill_4822_Desc_15 = {
    Text = "Tinct ganha <Energy:[Energy:Arg1]> de Fúria, <ExaltIconKeywords:Despertar>: O Dano básico do \"golpear\" de Tinct +[Arg2]%, todas as cartas de Tinct ganham 1 efeito aleatório, que será removido ao final da batalha. A primeira vez que Tinct Dispara uma \"Habilidade\" a cada turno, gera 1 \"golpear\" Temporário com 0 de Consumo de potência de cálculo, os efeitos aleatórios deste \"golpear\" x2."
  },
  Skill_4822_EffectNameList = {Text = "Fúria"},
  Skill_4822_Name = {
