  },
  Skill_4824_AwakerSkillBackgroundStory = {
    Text = "Liz ainda se lembra do dia em que ganhou a Chama Verde.\nA chama azulada dançava em sua palma, instigando-a a realizar seu desejo reprimido"
  },
  Skill_4824_Desc_0 = {
    Text = "Causa <Damage:[Damage:Arg2]> pontos de <PunctureDamagewords:Dano de perfuração> a inimigos aleatórios [Arg1] vezes, aplica [Arg3]% de dano de <IntoxicationIconKeywords:Envenenamento>. Quando não houver poder de cálculo suficiente, pode ser forçado a disparar, e o efeito muda para ganhar <Energy:[Energy:Arg4]> pontos de Fúria e consumo."
  },
  Skill_4824_Desc_1 = {
    Text = "Causar <Damage:[Damage:Arg2]> pontos de <PunctureDamagewords:Dano Penetrante> a um inimigo aleatório [Arg1] vezes, aplicando <IntoxicationIconKeywords:Veneno> com [Arg3]% de dano. No final do turno, se na mão ou no <DimensionalSpaceIconKeywords:Espaço Dimensional Ultra>, evoluir para \"<DerivativeCardKeywords_20:Chama Verde da Extinção>\". Se jogado forçosamente com Arithmetica insuficiente, o efeito muda para ganhar <Energy:[Energy:Arg4]> pontos de Aliemus e ficar Exausto."
  },
  Skill_4824_EffectNameList = {Text = "Dano"},
