  Skill_4842_AwakerSkillBackgroundStory = {
    Text = "A feiticeira que transcende dimensões conhece as leis de refração no domínio.\nEla sabe cada caminho e cada ponto de conexão.\nOs canais infinitos estão todos em sua mente.\nSendo assim, comprar materiais de outras dimensões é algo que ela naturalmente consegue"
  },
  Skill_4842_Desc_0 = {
    Text = "Daffodil ganha <Energy:[Energy:Arg1]> pontos de Aliemus. <ExaltIconKeywords:Gnose Despertar>: Para cada cartão de Daffodil que entra em <DimensionalSpaceIconKeywords:Ultra Espaço>, coloque 1 <DerivativeCardKeywords_4:\"Inspiração\"> na mão, desencadeando um máximo de 2 vezes por turno."
