  Skill_4845_BattleDesc_0 = {
    Text = "Causa <Damage:[Damage:Arg1]> pontos de <PunctureDamagewords:dano perfurante> e aplica uma quantidade igual de <IntoxicationIconKeywords:envenenamento>. <O07CardKeyWord:ritual>: Ganha [Power:Arg3]/[Power:Arg4]/[Power:Arg5] pontos de <PowerIconKeywords:força> e [TentaclePower:Arg3]/[TentaclePower:Arg4]/[TentaclePower:Arg5] pontos de <TentacleInjurieIconKeywords:dano de tentáculo>."
  },
  Skill_4845_BattleDesc_1 = {
