  Skill_59476_AwakerSkillBackgroundStory = {
    Text = "Antes de ouvir esta música, você nunca teve verdadeiros ouvidos. Depois de ouvi-la, nunca encontrará um som igual. Então, concentre-se, prenda a respiração e celebre esta rara melodia!"
  },
  Skill_59476_Desc_0 = {
    Text = "Hameln ganha <Energy:[Energy:Arg1]> pontos de Fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: No início do turno, adicione uma carta \"<DerivativeCardKeywords_64:Sinfonia da Harmonia>\" à mão. <DerivativeCardKeywords_61:><DerivativeCardKeywords_62:>"
  },
  Skill_59476_Desc_15 = {
    Text = "Hameln obtém <Energy:[Energy:Arg1]> Fúria. <ExaltIconKeywords:Despertar>: No início do turno, coloca 1 \"<DerivativeCardKeywords_64:Sinfonia da Harmonia>\" na mão. No início do turno, para cada Carta com \"Melodia em loop\" ou \"Melodia Carregada\", Hameln obtém <Energy:[Energy:Arg2]> Fúria. Ao liberar \"Nada da Origem\", para cada 2 Cartas de comando com \"Melodia em loop\" ou \"Melodia Carregada\" existentes, contagem de Dano +1 <DerivativeCardKeywords_61:><DerivativeCardKeywords_62:>"
  },
  Skill_59476_EffectNameList = {Text = "Fúria"},
  Skill_59476_Name = {
    Text = "Esta música merece elogios"
  },
  Skill_59477_AwakerSkillBackgroundStory = {
    Text = "De onde vem a música? Do ritual de adoração, do canto do fazendeiro, do grito do homem primitivo, do canto do rouxinol na primavera, do vento nas árvores e das ondas do mar, do tremor da terra e do desmoronamento das montanhas... ou do murmúrio dos deuses no caos primordial"
  },
  Skill_59477_BattleDesc_0 = {
    Text = "Causa aleatoriamente [Arg3] vezes <Damage:[Damage:Arg1]> pontos de <PunctureDamagewords:dano de perfuração>. A cada dano causado: reduza temporariamente a <ExhaustionIconKeywords:força> do alvo em [Exhaustion:Arg2]; ganhe [Power:Arg2] <PowerIconKeywords:Força temporária>. Escolha 1 carta de comando não derivada na mão que não tenha <DepleteIconKeywords:Consumo>, <HuihuanaKeywords:Melodia em loop> ou <XushiAKeywords:Melodia Carregada> para adicionar \"<HuihuanaKeywords:Melodia em loop>\". Se não houver cartas na mão que possam ser adicionadas, cause 3 danos adicionais"
  },
  Skill_59477_BattleDesc_2 = {
    Text = "Causa aleatoriamente [Arg3] vezes <Damage:[Damage:Arg1]> pontos de <PunctureDamagewords:dano de perfuração>. A cada dano causado: reduza temporariamente a <ExhaustionIconKeywords:força> do alvo em [Exhaustion:Arg2]; ganhe [Power:Arg2] <PowerIconKeywords:Força temporária>. Escolha 1 carta de comando não derivada na mão que não tenha <DepleteIconKeywords:Consumo>, <HuihuanaKeywords:Melodia em loop> ou <XushiAKeywords:Melodia Carregada> para adicionar \"<HuihuanbKeywords:Melodia em loop>\". Se não houver cartas na mão que possam ser adicionadas, causa 3 danos adicionais"
  },
  Skill_59477_Desc_0 = {
    Text = "Causa aleatoriamente <Damage:[Damage:Arg1]> pontos de <PunctureDamagewords:Dano de perfuração> 3 vezes. A cada 1 Dano causado, <TouquKeywords:rouba> [Arg2] pontos de <PowerIconKeywords:Força> do alvo. Escolhe 1 Carta de comando na mão que não possua \"Melodia\", não consumível e não derivada, e adiciona \"<HuihuanaKeywords:Melodia em loop>\". Caso não haja cartas na mão que possam receber a adição, causa 3 vezes de Dano extra em vez disso."
  },
  Skill_59477_Desc_2 = {
    Text = "Causa aleatoriamente <Damage:[Damage:Arg1]> pontos de <PunctureDamagewords:Dano de perfuração> 3 vezes. A cada 1 Dano causado, <TouquKeywords:rouba> [Arg2] pontos de <PowerIconKeywords:Força> do alvo. Escolhe 1 Carta de comando na mão que não possua \"Melodia\", não consumível e não derivada, e adiciona \"<HuihuanbKeywords:Melodia em loop>\". Caso não haja cartas na mão que possam receber a adição, causa 3 vezes de Dano extra em vez disso."
  },
