  Skill_61121_AwakerSkillBackgroundStory = {
    Text = "Atropos cortou o fio negro, cessando o destino dos Tilosianos.\nO assassino que usava grilhões como armas, outrora valente,\nfinalmente caiu diante de inúmeras lanças"
  },
