  Skill_61122_AwakerSkillBackgroundStory = {
    Text = "Atropos cortou o fio negro, cessando o destino dos Tilosianos.\nO assassino que usava grilhões como armas, outrora valente,\nfinalmente caiu diante de inúmeras lanças"
  },
  Skill_61122_BattleDesc = {
    Text = "Considerado como \"golpe\". Causa <Damage:[Damage:Arg1]> pontos de dano, este dano recebe um bônus de 5 vezes na força e ativa <BleedingIconKeywords:sangramento> 30% do alvo, recuperando [Arg3]% da vida perdida (<Heal:[Arg2]>). Após ser jogado, transforma-se em \"<DerivativeCardKeywords_65:Cadeia de Sangue>\"."
  },
  Skill_61122_Desc = {
    Text = "Considerado como \"ataque\". Causa <Damage:[Damage:Arg1]> pontos de dano, este dano recebe um bônus de 5 vezes no poder e ativa <BleedingIconKeywords:sangrando> 30% do alvo, recuperando 15% da vida perdida. Após ser jogado, transforma-se em \"<DerivativeCardKeywords_65:cadeia de sangue>\""
