  },
  Skill_61123_AwakerSkillBackgroundStory = {
    Text = "Cante, ó deusa! Cante do destino da filha de Delos:\nRepleta de sangue e lágrimas, raiva e desespero.\nSeu ódio arde como fogo, consumindo tudo ao redor,\nE no fim, traz sua própria morte"
  },
  Skill_61123_Desc_0 = {
    Text = "Helot: Catena Hilo ganha <Energy:[Energy:Arg1]> pontos de aliemus. <ExaltIconKeywords:Rouse Gnosis>: Coloca um \"<DerivativeCardKeywords_65:Blood Chain>\" cartão na sua mão; o cartão de comando de Helot: Catena Hilo ganha \"<RetainIconKeywords:Retain>\". No início do turno, o dano base de Helot: Catena Hilo nesta batalha aumenta em [Arg2]%."
  },
  Skill_61123_Desc_15 = {
    Text = "Helot: Catena ganha <Energy:[Energy:Arg1]> de Fúria. <ExaltIconKeywords:Despertar>: Colocar uma \"<DerivativeCardKeywords_65:Cadeia de Sangue>\" na mão, e as Cartas de comando de Helot: Catena ganham \"<RetainIconKeywords:Preservar>\". No início do turno, Dano básico de Helot: Catena +[Arg2]% para esta batalha. Após desencadear Fúria Explosiva \"Cadeias de Restrição\", conceder a cada Carta de comando única de \"Helot: Catena\" na mão 35 capas de <TempPowerKeywords:Reforço Temporário>."
  },
  Skill_61123_EffectNameList = {
    Text = "Loucura, aumento de dano"
  },
  Skill_61123_Name = {
    Text = "Declaração do Ceifador de Almas"
  },
