  },
  Skill_61124_Desc_0 = {
    Text = "[<DevouredIconKeywords:Devorar> : Compre 1 carta de comando de Cadeia de Sangue: Hilota, reduzindo o consumo de potência de cálculo das cartas de comando de Cadeia de Sangue: Hilota em 1.] Neste turno, quando Cadeia de Sangue: Hilota causar dano ativo, aplica [Arg2]% de <BleedingIconKeywords:sangramento>. Causa <Damage:[Damage:Arg1]> pontos de dano."
  },
  Skill_61124_Desc_3 = {
    Text = "[[<DevouredIconKeywords:Devorar> : Comprar 1 carta de comando de Helot: Catena, reduzindo o consumo de potência de cálculo das cartas de comando de Helot: Catena na mão em 1.] Quando Helot: Catena causar Dano ativo neste turno, aplica [Arg2]%<BleedingIconKeywords:Sangramento>. Quebra o Escudo do alvo, causa <Damage:[Damage:Arg1]> pontos de Dano e impede o alvo de obter Escudo por 1 turno."
