  Skill_66349_Desc_0 = {
    Text = "Se estiver na mão, se o cartão no topo do baralho for uma carta de comando, transforme-se em uma cópia dela. Após jogar, retorne, ganhando <Energy:[Energy:Arg1]> pontos de aliemus"
