  Skill_66350_AwakerSkillBackgroundStory = {
    Text = "Atravessando a porta da chave de prata, os humanos se curvam diante de Seu trono, em busca da resposta suprema.\nE ela é a guardiã, responsável por dissuadir, alertar e advertir.\nO não informar é a sua misericórdia"
  },
  Skill_66350_BattleDesc_0 = {
    Text = "Tawil obtém <Energy:[Energy:Arg1]> de Fúria. Coloca 1 \"<DerivativeCardKeywords_67:Luz do Amanhecer da Chave de Prata>\" na mão. Quando Tawil consome Poder de cálculo, a Energia da Chave de Prata ganha +50%."
  },
  Skill_66350_BattleDesc_15 = {
    Text = "Tawil ganha <Energy:[Energy:Arg1]> de Fúria. Coloca 1 \"<DerivativeCardKeywords_67:Luz do Amanhecer da Chave de Prata>\" na mão. Quando Tawil consome Poder de cálculo, a Energia da Chave de Prata ganha aumenta em 50%. Após Tawil desencadear a Fúria Explosiva, todas as Cartas de comando dos Corpos Despertos neste turno ganham [Arg2]% de bônus de Dano Final, e a próxima Carta de comando disparada por outro Corpo Desperto é acionada mais uma vez."
  },
  Skill_66350_Desc_0 = {
    Text = "Tawil obtém <Energy:[Energy:Arg1]> de Fúria. Coloca 1 \"<DerivativeCardKeywords_67:Luz do Amanhecer da Chave de Prata>\" na mão. Quando Tawil consome Poder de cálculo, a Energia da Chave de Prata ganha +50%."
