  Skill_66355_BattleDesc = {
    Text = "Pode gastar <Posse:500> pontos de energia da chave de prata para disparar quando a aritmética for insuficiente. Causa 4 vezes <Damage:[Damage:Arg1]> de dano, compre 1 carta. Para cada vez que causar dano, reduza temporariamente o alvo em [Exhaustion:Arg2] pontos <ExhaustionIconKeywords:força> e ganhe [Power:Arg2] pontos <PowerIconKeywords:Força temporária>. Embaralhe <DerivativeCardKeywords_77:\"Seis asas desdobradas\"> no mazo de compra."
  },
  Skill_66355_Desc = {
    Text = "Quando a aritmética é insuficiente, você pode consumir <Posse:500> flare da chave para jogar. Inflige <Damage:[Damage:Arg1]> dano 4 vezes, puxa 1 cartão. Para cada instância de dano, <TouquKeywords:roubar> [Arg2] <PowerIconKeywords:força> temporária do alvo. Embaralhe <DerivativeCardKeywords_77:\"seis asas\"> no seu monte de compra."
