  Skill_66356_tempOverLimitUtlSkillDesc_1 = {
    Text = "O dano, Escudo e recuperação de Vida causados por Tawil aumentam temporariamente em [Arg2]%, o Dano Final das próprias Cartas de comando neste turno +15%. Obtém 3 pontos de Poder de cálculo e <Posse:[Arg1]> pontos de Energia da Chave de Prata. <FaxianKeywords:Descobre> 10 cartas de habilidade do Domínio atual, escolhe até 3 para colocar na mão e faz com que sejam tratadas como cartas de Tawil; essas cartas obtêm <DepleteIconKeywords:Consumir> e <RetainIconKeywords:Preservar>. A próxima Carta de comando de Tawil disparada entra em vigor 2 vezes."
  },
  Skill_66356_tempOverLimitUtlSkillDesc_2 = {
    Text = "O dano, Escudo e recuperação de Vida causados por Tawil aumentam temporariamente em [Arg2]%, o Dano Final das próprias Cartas de comando neste turno +15%. Obtém 3 pontos de Poder de cálculo e <Posse:[Arg1]> pontos de Energia da Chave de Prata. <FaxianKeywords:Descobre> 10 cartas de habilidade do Domínio atual, escolhe até 3 para colocar na mão e faz com que sejam tratadas como cartas de Tawil; essas cartas obtêm <DepleteIconKeywords:Consumir> e <RetainIconKeywords:Preservar>. A próxima Carta de comando de Tawil disparada entra em vigor 2 vezes."
  },
  Skill_66356_tempOverLimitUtlSkillDesc_3 = {
    Text = "O dano, Escudo e recuperação de Vida causados por Tawil aumentam temporariamente em [Arg2]%, o Dano Final das Cartas de comando de todos os Corpos Despertos neste turno aumenta em 15%. Obtém 3 pontos de Poder de cálculo e <Posse:[Arg1]> pontos de Energia da Chave de Prata. <FaxianKeywords:Descobre> 10 cartas de habilidade do Domínio atual, escolhe até 3 para colocar na mão e faz com que sejam tratadas como cartas de Tawil; essas cartas obtêm <DepleteIconKeywords:Consumir>, <PrepareKeypvewords1:Pronto1> e <RetainIconKeywords:Preservar>. A próxima Carta de comando de Tawil disparada e as Cartas de comando dos outros Corpos Despertos entram em vigor 2 vezes cada."
  },
