  },
  Skill_70299_AwakerSkillBackgroundStory = {
    Text = "O fim que ela buscou durante toda a vida agora está bem diante de seus olhos. \n A porta negra emana uma atração mortal. \n Antes de abrir a porta, ela imaginou 372 possibilidades de verdade. \n Depois de abrir a porta, resta apenas a 373ª que ela não quer admitir. \n Sem escolha, ela só pode cair. \n Que má sorte, ela e o mundo todo."
  },
  Skill_70299_BattleDesc = {
    Text = "Os outros Corpos Despertos obtêm <Energy:[Energy:Arg1]> de Fúria, infligem [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"capa\" plural=\"capas\"> de <IntoxicationIconKeywords:Envenenamento> em todos os inimigos e aumentam temporariamente o Dano potencializado da equipe em [Arg3]%."
  },
  Skill_70299_Desc = {
    Text = "Os outros Corpos Despertos obtêm <Energy:[Energy:Arg1]> de Fúria, infligem [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"capa\" plural=\"capas\"> de <IntoxicationIconKeywords:Envenenamento> em todos os inimigos e aumentam temporariamente o Dano potencializado da equipe em [Arg3]%. \"Forma Final\": Compra 3 cartas adicionais, obtém 3 de Poder de cálculo, aciona 50% do <IntoxicationIconKeywords:Envenenamento> em todos os inimigos e aumenta o Aliemus Base de \"Fusão · Dor\" em 50, até 3 vezes."
  },
  Skill_70299_EffectNameList = {
    Text = "Loucura, Veneno, Dano Potente"
  },
  Skill_70299_Name = {
    Text = "Ponto Final, Porta dos Abismos e da Verdade"
  },
  Skill_70299_OverLimitUtlSkillDesc = {
    Text = "Os outros Corpos Despertos obtêm <Energy:[Energy:Arg4]> de Fúria, infligem [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"capa\" plural=\"capas\"> de <IntoxicationIconKeywords:Envenenamento> em todos os inimigos, aumentam temporariamente o Dano potencializado da equipe em [Arg3]% e aumentam o <IntoxicationIconKeywords:Envenenamento>, o <RetaliateIconKeywords:Contrataque> e o Dano básico de todos os Corpos Despertos em 10%. Em Batalhas do Líder, obtém uma capa adicional de \"Chamado Final\"."
  },
  Skill_70299_PropertyNameList = {
    Text = "$GrowValue1,Poder de ataque*GrowValue2,$GrowValue3%"
  },
  Skill_70300_AwakerSkillBackgroundStory = {
    Text = "Quando a cápsula carmesim se expande sob a armadura mecânica, o ressonador de latão tece uma matriz de defesa em forma de colmeia.\n A rede de pulsos de micélio rasga o espaço, e a névoa ácida grava inscrições de aviso, enquanto o feixe de desmembramento de memória está pré-aquecendo — todo sangue e carne que tocarem a fronteira, acabarão se tornando amostras contorcidas no recipiente de cultivo."
  },
  Skill_70300_BattleDesc = {
    Text = "Adquira <Block:[Block:Arg1]> pontos de escudo. Adquira <Energy:[Energy:Arg2]> pontos de aliemus"
  },
  Skill_70300_Desc = {
    Text = "Adquira <Block:[Block:Arg1]> pontos de escudo. \"Fusão·Boneca\" adquire <Energy:[Energy:Arg2]> pontos de aliemus."
  },
  Skill_70300_EffectNameList = {
