  },
  Skill_70300_Name = {Text = "Defesa"},
  Skill_70300_PropertyNameList = {
    Text = "Defesa *GrowValue1,$GrowValue2"
  },
  Skill_70301_AwakerSkillBackgroundStory = {
    Text = "As pinças vêm de seu passado, de sua raça, são o poder que ela nunca abandonou.\nO que significa aquele sorriso que floresce ao perfurar o peito do inimigo com essas pinças?\n\n?"
  },
  Skill_70301_BattleDesc = {
    Text = "Causa <Damage:[Damage:Arg1]> pontos de dano. Ganha <Energy:[Energy:Arg2]> pontos de aliemus"
  },
  Skill_70301_Desc = {
    Text = "Causa <Damage:[Damage:Arg1]> pontos de dano. \"Fusão·Doll\" ganha <Energy:[Energy:Arg2]> pontos de aliemus."
  },
  Skill_70301_EffectNameList = {
