  },
  Skill_70301_Name = {Text = "golpear"},
  Skill_70301_PropertyNameList = {
    Text = "Poder de ataque*GrowValue1,$GrowValue2"
  },
  Skill_70302_AwakerSkillBackgroundStory = {
    Text = "Ela se sacrificou, obtendo assim o direito de tocar a realidade.\nQuando ela recolheu a mão, sua alma já estava derretida como cera."
  },
  Skill_70302_BattleDesc_0 = {
    Text = "\"Fusão · Dor\" ganha <Energy:[Energy:Arg1]> Fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: No fim do turno, recupere <Heal:[Heal:Arg2]> Vida e ganhe <Energy:[Energy:Arg4]> Fúria. \"Forma Final\": Não recupera mais Vida; em vez disso aciona [Arg3]% de <IntoxicationIconKeywords:Envenenamento> em todos os inimigos."
  },
  Skill_70302_BattleDesc_15 = {
    Text = "\"Fusão · Dor\" ganha <Energy:[Energy:Arg1]> Fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: Para cada capa de \"Chamado Final\", Dano potencializado +8%. \"Fim do Néant\" concede a todos os Corpos Despertos 30% de Fúria Básica. No fim do turno, recupere <Heal:[Heal:Arg2]> Vida e ganhe <Energy:[Energy:Arg4]> Fúria. \"Forma Final\": Não recupera mais Vida, em vez disso aciona [Arg3]% de <IntoxicationIconKeywords:Envenenamento> em todos os inimigos."
  },
  Skill_70302_Desc_0 = {
    Text = "\"Doll: Inferno\" ganha <Energy:[Energy:Arg1]> pontos de Fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: Ao final do turno, recupera <Heal:[Heal:Arg2]> pontos de Vida e ganha Fúria equivalente à sua Recarga de raiva. \"Fim\": Não recupera mais Vida, em vez disso, ativa [Arg3]% de <IntoxicationIconKeywords:Envenenamento> em todos os inimigos."
  },
  Skill_70302_Desc_15 = {
    Text = "\"Fusão · Dor\" ganha <Energy:[Energy:Arg1]> Fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: Para cada capa de \"Chamado Final\", Dano potencializado +8%. \"Fim do Néant\" concede a todos os Corpos Despertos 30% de Fúria Básica. No fim do turno, recupere <Heal:[Heal:Arg2]> Vida e ganhe Fúria igual à Fúria Regenerativa. \"Forma Final\": Não recupera mais Vida, em vez disso aciona [Arg3]% de <IntoxicationIconKeywords:Envenenamento> em todos os inimigos."
  },
  Skill_70302_EffectNameList = {
    Text = "Aliemus, recuperação, proporção de veneno"
  },
  Skill_70302_Name = {
    Text = "Peste de almas"
  },
  Skill_70302_PropertyNameList = {
