  },
  Skill_78784_Desc = {
    Text = "Cada camada de \"empatia\" removida do próprio personagem aplica 1 camada de \"medo fixo\" a todos os inimigos. Cada camada de \"medo fixo\" reduz o dano causado pelo alvo em 3%."
  },
  Skill_78784_Name = {
    Text = "Conversão: Fixação Fóbica"
  },
  Skill_78785_AwakerSkillBackgroundStory = {
    Text = "\"Por favor, me diga, quem é você realmente?\"\n Ao ouvir isso, ela começou a rir.\n O pobre paciente, é claro, não podia responder, pois sua memória havia sido alterada; quanto mais ele buscasse, mais se aproximaria da aterradora existência implantada na memória — até que sua percepção colapsasse completamente e ele se tornasse um monstro."
  },
  Skill_78785_BattleDesc_0 = {
    Text = "Remova toda <AnalysisKeywords0:Empatia> de si mesmo e escolha transformá-la em <D13AFKeyWord2:Trauma psicológico> ou <D13AFKeyWord1:Fixação Fóbica> em todos os inimigos [Arg6] vezes. Causa <Damage:[Damage:Arg1]> pontos de dano a todos os inimigos e ganha <Posse:[Arg3]> pontos de Energia de chave."
  },
  Skill_78785_BattleDesc_2 = {
    Text = "Remova toda <AnalysisKeywords0:Empatia> de si mesmo e escolha transformá-la em <D13AFKeyWord2:Trauma psicológico> ou <D13AFKeyWord1:Fixação Fóbica> em todos os inimigos. Para cada camada removida, aumenta o Dano básico causado por Clementine em 3%. Causa <Damage:[Damage:Arg1]> pontos de dano a todos os inimigos [Arg6] vezes e ganha <Posse:[Arg3]> pontos de Energia de chave."
  },
  Skill_78785_BattleDesc_3 = {
    Text = "Remova toda <AnalysisKeywords3:Empatia> de si mesmo e escolha transformá-la em <D13AFKeyWordQ2:Trauma psicológico> ou <D13AFKeyWordQ1:Fixação Fóbica> em todos os inimigos. Para cada camada removida, o Dano básico causado por Clementine aumenta em 3%. Causa <Damage:[Damage:Arg1]> pontos de dano a todos os inimigos [Arg6] vezes e ganha <Posse:[Arg3]> pontos de Energia de chave."
