  },
  Skill_83780_AwakerSkillBackgroundStory = {
    Text = "As nuvens informarão sobre a mudança do clima, as ondas contarão sobre a mudança das correntes oceânicas, mas quando a tempestade realmente chegar, mesmo os maiores navios só poderão flutuar impotentemente. \n Neste momento, os cálculos e orientações do navegador são a última rota de fuga de todos os sobreviventes. \n Portanto, cumpra seu dever, mesmo que os relâmpagos o atinjam, deve brilhar uma luz mesmo na dor, indicando a direção da costa. \n Essa é a missão que você deve cumprir."
  },
  Skill_83780_BattleDesc_0 = {
    Text = "Adquira <Block:[Block:Arg1]> pontos de escudo e [Arg2] tentáculos temporários. Descarte todas as cartas da mão e compre a mesma quantidade de cartas."
  },
  Skill_83780_BattleDesc_3 = {
    Text = "Adquira <Block:[Block:Arg1]> pontos de escudo e [Arg2] tentáculos temporários. <VulnerabilityIconKeywords:vulnerável> a todos os inimigos por 1 turno, aumentando o dano crítico temporário em [Arg5]%. Descarte todas as cartas da mão e compre a mesma quantidade de cartas."
  },
  Skill_83780_Desc_0 = {
