  Skill_89776_AwakerSkillBackgroundStory = {
    Text = "\"Maninho, você disse que se voarmos com asas, até onde conseguimos chegar? Podemos voar acima das nuvens, tocar a lua e as estrelas?\"\n\"Talvez... seja possível? Mas precisamos de um par de asas grandes e fortes.\"\nA galáxia profunda e sonhadora e as constelações do manuscrito se refletiram nos sonhos pesados das duas crianças, transformando-se em uma semente de desejo, enterrada em seus corações."
  },
  Skill_89776_Desc_0 = {
    Text = "Castor ganha <Energy:[Energy:Arg1]> pontos de fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: O dano causado por Castor será sempre um golpe crítico, e ao disparar \"<DerivativeCardKeywords_107:Pluma Negra>\", aplica [Corrosion:Arg2] camadas de <Corrosion:Corrosão> ao alvo, e o escudo preservado é aumentado em 50%."
  },
  Skill_89776_Desc_15 = {
    Text = "Castor ganha <Energy:[Energy:Arg1]> pontos de fúria. <ExaltIconKeywords:Despertar do Conhecimento Espiritual>: O dano causado por Castor será sempre um golpe crítico, e ao disparar \"<DerivativeCardKeywords_107:Pluma Negra>\", aplica [Corrosion:Arg2] camadas de <Corrosion:Corrosão> ao alvo, e o escudo preservado é aumentado em 50%. A primeira vez que \"Pluma Negra\" for Disparada a cada turno, infligir Corrosão igual ao Talento \"Plumas Santificadas de Purificação\" em todos os inimigos da linha da frente, e a Vida perdida quando a Corrosão é removida aumenta de 300% para 500%."
  },
