  Skill_89777_BattleDesc_0 = {
    Text = "Causa <Damage:[Damage:Arg1]> de dano. Ganha <Energy:[Energy:Arg2]> de frenesi. <WormholeKeywords:Telecinese>: Embaralhe 1 \"<DerivativeCardKeywords_107:Pluma Negra>\" no seu deck de compra e ganha <Block:[Block:Arg3]> de bloqueio."
