  Skill_89778_AwakerSkillBackgroundStory = {
    Text = "Ele é tolo, teimoso e nunca muda. Mesmo que só consiga emitir um grito solitário, não se submeterá a nenhuma corrente ou lâmina. Ele usará seu bico afiado, que nunca foi desgastado, para bicar cada fenda da jaula. Quando as asas negras rasgarem a borda da noite, ele levará aquela última pena, junto com sua sombra, e voará em direção à luz do dia do outro lado da tempestade."
  },
  Skill_89778_Desc = {
