  Skill_89780_AwakerSkillBackgroundStory = {
    Text = "Para combater a exploração cruel e enfrentar as perdas repetidas, ele manterá estas asas para sempre diante do irmão mais novo, até que cada pena se torne cinza e ele adentre primeiro as portas da morte."
  },
  Skill_89780_BattleDesc_0 = {
    Text = "Adquira <Block:[Block:Arg1]> pontos de escudo. Adquira <Energy:[Energy:Arg2]> pontos de aliemus. <WormholeKeywords:Telecinese>: Misture 1 carta \"<DerivativeCardKeywords_107:Pluma Negra>\" no baralho de compra e adquira <Block:[Block:Arg3]> pontos de escudo."
