  Skill_89781_AwakerSkillBackgroundStory = {
    Text = "Suas asas se abriram, como um amplo escudo, cada pena conectada a um esqueleto resistente, tremendo suavemente acima de sua cabeça.\n Aquela sombra negra o envolveu, bloqueando toda luz do sol, vento, chuva e dano, sustentando um céu seguro.\n \"Não a toque, deixe essas maldições sombrias retornarem ao peito dos agressores.\""
  },
  Skill_89781_Desc_0 = {
    Text = "Ganha <Block:[Block:Arg1]> pontos de escudo, <WeaknessIconKeywords:Fraqueza> todos os inimigos por 1 turno. <WormholeKeywords:Telecinese>: Misture 1 carta \"<DerivativeCardKeywords_107:Pluma Negra>\" no baralho de compras e ganhe <Block:[Block:Arg3]> pontos de escudo."
  },
  Skill_89781_Desc_2 = {
