  Skill_89782_AwakerSkillBackgroundStory = {
    Text = "Ele não é acostumado a suportar, e suas asas também podem levantar vórtices de fúria.\nToda carne será rasgada pelos dentes afiados do vento, sendo envolvida em sangue para o ventre da morte.\nMas não tenha medo, ele colocará seu nome no olho do furacão, o mais tranquilo centro.\n\n."
  },
  Skill_89782_Desc_0 = {
    Text = "Cause <Damage:[Damage:Arg1]> pontos de dano [Arg2] vezes, aumentando em [Arg3]% o dano crítico temporário dos outros aliados. <WormholeKeywords:Telecinese>: Misture 1 carta \"<DerivativeCardKeywords_107:Pluma Negra>\" no baralho de compras e ganhe <Block:[Block:Arg4]> pontos de escudo."
  },
  Skill_89782_Desc_2 = {
