  Skill_95811_AwakerSkillBackgroundStory = {
    Text = "O papel do convite é feito de pele suave. A decoração do convite vem de um crânio liso. As palavras do convite vêm de sangue fresco. A assinatura do convite é do caloroso anfitrião do Palácio Real.\nDoresain lhe envia um convite sincero, convidando-o para este banquete que pertence a vocês."
  },
  Skill_95811_Desc_0 = {
    Text = "Doresain ganha <Energy:[Energy:Arg1]> Fúria. <ExaltIconKeywords:Despertar>: Ganha [Power:Arg2] <PowerIconKeywords:STR>, e o dano causado por Doresain ganha um bônus adicional de [Arg3]% de STR. Na primeira vez que Doresain realiza uma Eliminação a cada turno, causa <RealDamage:Dano Fixo> igual a 50% do dano excedente aos outros inimigos."
  },
  Skill_95811_Desc_15 = {
    Text = "Doresain ganha <Energy:[Energy:Arg1]> Fúria. <ExaltIconKeywords:Despertar>: Ganha [Power:Arg2] <PowerIconKeywords:STR>. O dano causado por Doresain ganha um bônus extra de [Arg3]% de STR. Causa Dano Fixo igual a [Arg4]% da Vida atual a todos os inimigos. Após a primeira Eliminação de Doresain a cada turno, causa <RealDamage:Dano Fixo> aos outros inimigos igual a 100% do dano excedente."
